('de9f695d-6410-54f7-9890-c8684d595931', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 1, 1, 'A girl walks 12 m east and then 5.0 m north. Calculate the magnitude of her resultant displacement.', NULL, 1, 'numeric'::answer_type, '13', 'm', false, NULL, false, NULL, 's = √(12² + 5.0²) = 13 m. Mark scheme (2 marks). C1: Pythagoras. A1: s = 13 m.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg7e0a2455-t fg7e0a2455-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7e0a2455-t">Two displacements</title><desc id="fg7e0a2455-d">Displacements of 12 m east and 5.0 m north drawn head to tail, with the resultant dashed.</desc><line x1="56.8" y1="191.3" x2="296.9" y2="191.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="303.2,191.3 295,195.1 295,187.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="205.3" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">12 m</text><line x1="303.2" y1="191.3" x2="303.2" y2="95" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="303.2,88.7 307,96.8 299.4,96.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="317.2" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">5.0 m</text><line x1="56.8" y1="191.3" x2="297.3" y2="91.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="303.2,88.7 297.1,95.3 294.2,88.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185.4" y="152.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="56.8" cy="191.3" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Displacements of 12 m east and 5.0 m north drawn head to tail, with the resultant dashed.'),
('09bf3364-1ed5-5c2e-8b16-65080366dd9f', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 2, 2, 'Two displacements are added by drawing them head to tail. What represents the resultant?', NULL, 1, 'multiple_choice'::answer_type, 'The arrow from the tail of the first to the head of the last', NULL, false, NULL, false, NULL, 'This is the triangle (head-to-tail) rule. Mark scheme (1 mark). B1: C (The arrow from the tail of the first to the head of the last).', 1, NULL, NULL),
('a9ac3e60-b1af-55a3-bae2-5067df73a3ed', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 3, 3, 'Displacements of 7.0 m and 3.0 m are added. Calculate the largest possible resultant.', NULL, 1, 'numeric'::answer_type, '10', 'm', false, NULL, false, NULL, 'Largest when in the same direction: 7.0 + 3.0 = 10 m. Mark scheme (2 marks). C1: same direction. A1: s_max = 10 m.', 2, NULL, NULL),
('2a802329-1dfe-5f92-99a4-f9446bd49b05', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 4, 4, 'What is the minimum size of the resultant when displacements of 7.0 m and 3.0 m are combined in any directions?', NULL, 1, 'numeric'::answer_type, '4', 'm', false, NULL, false, NULL, 'Smallest when opposite: 7.0 − 3.0 = 4.0 m. Mark scheme (2 marks). C1: opposite directions. A1: s_min = 4.0 m.', 2, NULL, NULL),
('b218f7e2-fee4-550d-907c-3ed5dfac6058', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 5, 5, 'A scale drawing uses 1 cm to represent 2 km. How long is the arrow for a 7 km displacement?', NULL, 1, 'multiple_choice'::answer_type, '3.5 cm', NULL, false, NULL, false, NULL, 'Length = 7 ÷ 2 = 3.5 cm. Mark scheme (1 mark). B1: A (3.5 cm).', 1, NULL, NULL),
('b8d54fd0-9f30-508c-80b2-f84c442d3373', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 6, 6, 'On a scale drawing where 1 cm represents 50 m, the resultant arrow is 6.4 cm long. What displacement does it represent?', NULL, 1, 'numeric'::answer_type, '320', 'm', false, NULL, false, NULL, 's = 6.4 × 50 = 320 m. Mark scheme (2 marks). C1: length × scale. A1: s = 320 m.', 2, NULL, NULL),
('ac8649a3-eb8c-5511-b0cc-5ea2db602753', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 7, 7, 'A rambler walks 9.0 km north then 12 km west. Calculate the magnitude of her displacement.', NULL, 1, 'numeric'::answer_type, '15 km', 'km', false, NULL, false, NULL, 's = √(9.0² + 12²) = 15 km. Mark scheme (2 marks). C1: Pythagoras. A1: s = 15 km.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgbc31eb72-t fgbc31eb72-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbc31eb72-t">Two displacements</title><desc id="fgbc31eb72-d">Displacements of 9.0 km north and 12 km west drawn head to tail, with the resultant dashed.</desc><line x1="296.4" y1="227.3" x2="296.4" y2="59" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,52.7 300.2,60.8 292.6,60.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="310.4" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">9.0 km</text><line x1="296.4" y1="52.7" x2="69.9" y2="52.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="63.6,52.7 71.7,48.9 71.7,56.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="38.7" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">12 km</text><line x1="296.4" y1="227.3" x2="68.6" y2="56.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="63.6,52.7 72.4,54.5 67.8,60.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="188.4" y="128.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="296.4" cy="227.3" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Displacements of 9.0 km north and 12 km west drawn head to tail, with the resultant dashed.'),
('f6dc46e4-82f5-5e27-847a-c608cf3359ab', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 8, 8, 'Why must a scale drawing of displacements use the same scale for every arrow?', NULL, 1, 'multiple_choice'::answer_type, 'So that the lengths can be compared and the resultant read correctly', NULL, false, NULL, false, NULL, 'Mixing scales would distort the triangle. Mark scheme (1 mark). B1: D (So that the lengths can be compared and the resultant read correctly).', 1, NULL, NULL),
('b2b6385d-e8e9-5ccf-a7d1-1a5841121130', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 9, 9, 'A ship sails 6.0 km north and then 8.0 km east. Calculate the angle of its resultant displacement east of north.', NULL, 1, 'numeric'::answer_type, '53.13', '°', false, NULL, false, NULL, 'θ = tan⁻¹(8.0 ÷ 6.0) = 53.1°. Mark scheme (2 marks). C1: tan θ = 8.0/6.0. A1: θ = 53.1°.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg86f4ffa8-t fg86f4ffa8-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg86f4ffa8-t">Ship displacement</title><desc id="fg86f4ffa8-d">A ship sails 6.0 km north then 8.0 km east; the resultant is dashed and its angle θ east of north is marked.</desc><line x1="63.6" y1="227.3" x2="63.6" y2="59" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="63.6,52.7 67.4,60.8 59.8,60.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="49.6" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">6.0 km</text><line x1="63.6" y1="52.7" x2="290.1" y2="52.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,52.7 288.3,56.5 288.3,48.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="38.7" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">8.0 km</text><line x1="63.6" y1="227.3" x2="291.4" y2="56.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,52.7 292.2,60.6 287.6,54.5" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="171.6" y="128.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="63.6" cy="227.3" r="3.4" style="fill:currentColor;stroke:none"/><line x1="63.6" y1="227.3" x2="63.6" y2="183.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><path d="M63.6,197.3 A30,30 0 0,1 87.6,209.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="82.3" y="189.8" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ</text><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A ship sails 6.0 km north then 8.0 km east; the resultant is dashed and its angle θ east of north is marked.'),
('afc4317a-e0e9-57cf-8f01-9cd31171cf9c', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 10, 10, 'Two displacements are at right angles. Which method gives the magnitude of their resultant?', NULL, 1, 'multiple_choice'::answer_type, 'Pythagoras'' theorem', NULL, false, NULL, false, NULL, 'The resultant is the hypotenuse of a right-angled triangle. Mark scheme (1 mark). B1: B (Pythagoras'' theorem).', 1, NULL, NULL),
('70de672f-2222-58a5-b76a-e5c6d1ebca37', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 11, 11, 'A diver swims 15 m horizontally and 8.0 m vertically downwards. Calculate the magnitude of her displacement.', NULL, 1, 'numeric'::answer_type, '17', 'm', false, NULL, false, NULL, 's = √(15² + 8.0²) = 17 m. Mark scheme (2 marks). C1: Pythagoras. A1: s = 17 m.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg8791027b-t fg8791027b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg8791027b-t">Diver displacement</title><desc id="fg8791027b-d">A diver moves 15 m horizontally and 8.0 m vertically down; the resultant is dashed.</desc><line x1="56.8" y1="74.3" x2="296.9" y2="74.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="303.2,74.3 295,78.1 295,70.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="60.3" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">15 m</text><line x1="303.2" y1="74.3" x2="303.2" y2="199.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="303.2,205.7 299.4,197.5 307,197.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="317.2" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">8.0 m</text><line x1="56.8" y1="74.3" x2="297.6" y2="202.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="303.2,205.7 294.2,205.2 297.8,198.5" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="186.6" y="127.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="56.8" cy="74.3" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A diver moves 15 m horizontally and 8.0 m vertically down; the resultant is dashed.'),
('6ac778e1-6ae4-53aa-92d3-4c06d4aaeba6', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 12, 12, 'Does the order in which two displacements are added change the resultant?', NULL, 1, 'multiple_choice'::answer_type, 'No, the resultant is the same', NULL, false, NULL, false, NULL, 'Vector addition is commutative. Mark scheme (1 mark). B1: C (No, the resultant is the same).', 1, NULL, NULL),
('2650b7a9-1fc5-5f25-8da3-9192bfb50cc3', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 13, 13, 'A mouse runs 1.2 m east and then 0.50 m south. Calculate the magnitude of its displacement.', NULL, 1, 'numeric'::answer_type, '1.3', 'm', false, NULL, false, NULL, 's = √(1.2² + 0.50²) = 1.3 m. Mark scheme (1 mark). A1: s = 1.3 m.', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg43e996cd-t fg43e996cd-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg43e996cd-t">Mouse run</title><desc id="fg43e996cd-d">A mouse runs 1.2 m east then 0.50 m south; the resultant is dashed.</desc><line x1="63.6" y1="91.5" x2="290.1" y2="91.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,91.5 288.3,95.3 288.3,87.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="77.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">1.2 m</text><line x1="296.4" y1="91.5" x2="296.4" y2="182.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,188.5 292.6,180.4 300.2,180.4" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="310.4" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">0.50 m</text><line x1="63.6" y1="91.5" x2="290.6" y2="186.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,188.5 287.4,188.9 290.4,181.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185.4" y="127.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="63.6" cy="91.5" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A mouse runs 1.2 m east then 0.50 m south; the resultant is dashed.'),
('12af4930-609d-5bed-8670-c9f83d0f05ff', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 14, 14, 'A car drives 20 km east and then 20 km north. Calculate the magnitude of its displacement.', NULL, 1, 'numeric'::answer_type, '28.28 km', 'km', false, NULL, false, NULL, 's = √(20² + 20²) = 28.3 km. Mark scheme (2 marks). C1: Pythagoras. A1: s = 28.3 km.', 2, NULL, NULL),
('5542d88d-577c-5706-9852-9eac7da17052', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 15, 15, 'A car drives 20 km east and then 20 km north. In which direction is its resultant displacement?', NULL, 1, 'multiple_choice'::answer_type, 'North-east (bearing 045°)', NULL, false, NULL, false, NULL, 'Equal perpendicular components give 45°. Mark scheme (1 mark). B1: A (North-east (bearing 045°)).', 1, NULL, NULL),
('c0c96369-95ff-512e-91b1-ed44c1a39b3f', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 16, 16, 'Three displacements of 4.0 m, 5.0 m and 2.0 m all point due east. Calculate the resultant.', NULL, 1, 'numeric'::answer_type, '11', 'm', false, NULL, false, NULL, 's = 4.0 + 5.0 + 2.0 = 11 m east. Mark scheme (2 marks). C1: same direction, add. A1: s = 11 m.', 2, NULL, NULL),
('e7ffe104-7ff5-5609-825b-25473f542b5a', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 17, 17, 'A boy walks 50 m north and 50 m south. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'His resultant displacement is zero but he walked 100 m', NULL, false, NULL, false, NULL, 'Opposite equal displacements cancel. Mark scheme (1 mark). B1: D (His resultant displacement is zero but he walked 100 m).', 1, NULL, NULL),
('c5d8da8e-7772-53f4-acb1-b6c351568cc2', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 18, 18, 'On a map of scale 1 cm to 500 m, a walk is drawn as 3.0 cm north and then 4.0 cm east. What is the real resultant displacement, in m?', NULL, 1, 'numeric'::answer_type, '2500', 'm', false, NULL, false, NULL, 'Arrow length = √(3.0² + 4.0²) = 5.0 cm, so s = 5.0 × 500 = 2500 m. Mark scheme (2 marks). C1: scale applied. A1: s = 2500 m.', 2, NULL, NULL),
('f5442db6-3fb1-5914-9583-2f5c70256738', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 19, 19, 'Which method adds two vectors that are drawn starting from the same point?', NULL, 1, 'multiple_choice'::answer_type, 'The parallelogram method', NULL, false, NULL, false, NULL, 'Complete the parallelogram; its diagonal is the resultant. Mark scheme (1 mark). B1: D (The parallelogram method).', 1, NULL, NULL),
('611c54cf-b214-5f0a-ba73-5d75769d0d01', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 20, 20, 'A hiker walks 5.0 km east and then 8.0 km on a bearing of 030°. Using the cosine rule, calculate the magnitude of her displacement.', NULL, 2, 'numeric'::answer_type, '11.36 km', 'km', false, NULL, false, NULL, 'The angle between the legs inside the triangle is 120°. s = √(5.0² + 8.0² − 2 × 5.0 × 8.0 × cos 120°) = 11.4 km. Mark scheme (3 marks). C1: angle 120°. C1: cosine rule. A1: s = 11.4 km.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg4a42483e-t fg4a42483e-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4a42483e-t">Using the cosine rule</title><desc id="fg4a42483e-d">A hike of 5.0 km east followed by 8.0 km on a bearing of 030°; the resultant is dashed.</desc><line x1="63.6" y1="229.6" x2="186.6" y2="229.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="192.9,229.6 184.8,233.4 184.8,225.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="128.2" y="243.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">5.0 km</text><line x1="192.9" y1="229.6" x2="293.3" y2="55.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,50.4 295.7,59.3 289.1,55.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="256.8" y="147" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">8.0 km</text><line x1="63.6" y1="229.6" x2="291.4" y2="54.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,50.4 292.3,58.4 287.7,52.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="188.5" y="151.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="63.6" cy="229.6" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A hike of 5.0 km east followed by 8.0 km on a bearing of 030°; the resultant is dashed.'),
('adee174d-7701-5559-821b-eeeef07b0f08', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 21, 21, 'A boat sails 4.0 km on a bearing of 060° and then 4.0 km on a bearing of 120°. Calculate the magnitude of its displacement.', NULL, 2, 'numeric'::answer_type, '6.928 km', 'km', false, NULL, false, NULL, 'East: 4.0 sin 60° + 4.0 sin 120° = 6.928 km; north: 4.0 cos 60° + 4.0 cos 120° = 0. s = 4.0 × sin 60° × 2 = 6.93 km. Mark scheme (3 marks). C1: components. C1: resultant. A1: s = 6.93 km.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg71e54d48-t fg71e54d48-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg71e54d48-t">Two bearings</title><desc id="fg71e54d48-d">A boat sails 4.0 km on a bearing of 060° then 4.0 km on a bearing of 120°; the resultant is dashed.</desc><line x1="63.6" y1="173.6" x2="174.5" y2="109.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="180,106.4 174.8,113.8 171,107.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="114.8" y="127.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">4.0 km</text><line x1="180" y1="106.4" x2="291" y2="170.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,173.6 287.5,172.8 291.3,166.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="245.2" y="127.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 km</text><line x1="63.6" y1="173.6" x2="290.1" y2="173.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,173.6 288.3,177.4 288.3,169.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="159.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="63.6" cy="173.6" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A boat sails 4.0 km on a bearing of 060° then 4.0 km on a bearing of 120°; the resultant is dashed.'),
('c38c21be-6d1a-57b7-916f-dfe986b52462', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 22, 22, 'A displacement of 10 km is directed 30° north of east. Calculate its northward component.', NULL, 2, 'numeric'::answer_type, '5 km', 'km', false, NULL, false, NULL, 'North component = 10 sin 30° = 5.0 km. Mark scheme (3 marks). C1: sine for the component. C1: value. A1: s_N = 5.0 km.', 3, NULL, NULL),
('8dfa1f6e-d119-558e-9071-ea923b8bdc13', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 23, 23, 'A walker''s displacement is 10 km at 30° north of east. How far east of the start is she?', NULL, 2, 'numeric'::answer_type, '8.66 km', 'km', false, NULL, false, NULL, 'East component = 10 cos 30° = 8.66 km. Mark scheme (3 marks). C1: cosine for the component. C1: value. A1: s_E = 8.66 km.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg9abed08f-t fg9abed08f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9abed08f-t">Components of a displacement</title><desc id="fg9abed08f-d">A 10 km displacement at 30° north of east (dashed) with its east and north components drawn head to tail.</desc><line x1="60" y1="209.3" x2="293.7" y2="209.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,209.3 291.9,213.1 291.9,205.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="223.3" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)"></text><line x1="300" y1="209.3" x2="300" y2="77" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="300,70.7 303.8,78.9 296.2,78.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="314" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)"></text><line x1="60" y1="209.3" x2="294.6" y2="73.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="300,70.7 294.9,78.1 291.1,71.5" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="187" y="152.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">10 km</text><circle cx="60" cy="209.3" r="3.4" style="fill:currentColor;stroke:none"/><line x1="60" y1="209.3" x2="104" y2="209.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><path d="M90,209.3 A30,30 0 0,0 85.9,194.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="100.5" y="198.4" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">30°</text><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A 10 km displacement at 30° north of east (dashed) with its east and north components drawn head to tail.'),
('9da255c3-9f6b-511f-88a6-8d63f0bd8f47', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 24, 24, 'What is the parallelogram rule for adding two displacements?', NULL, 2, 'multiple_choice'::answer_type, 'Draw both from the same point, complete the parallelogram; the diagonal from that point is the resultant', NULL, false, NULL, false, NULL, 'It gives the same result as the triangle rule. Mark scheme (3 marks). C1: common origin. C1: diagonal is resultant. A1: B (Draw both from the same point, complete the parallelogram; the diagonal from that point is the resultant).', 3, NULL, NULL),
('f84e1b5f-cf55-55d3-a15d-e310f74a9cde', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 25, 25, 'A plane flies 200 km north then 150 km on a bearing of 090°, then 50 km south. Calculate the magnitude of the resultant displacement.', NULL, 2, 'numeric'::answer_type, '212.1 km', 'km', false, NULL, false, NULL, 'North: 200 − 50 = 150 km; east: 150 km. s = √(150² + 150²) = 212 km. Mark scheme (3 marks). C1: net components. C1: Pythagoras. A1: s = 212 km.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg0ac6a5dd-t fg0ac6a5dd-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg0ac6a5dd-t">Three-leg flight</title><desc id="fg0ac6a5dd-d">A flight of 200 km north, 150 km east and 50 km south; the resultant is dashed.</desc><line x1="109.5" y1="234" x2="109.5" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="109.5,46 113.3,54.2 105.7,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="95.5" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">200 km</text><line x1="109.5" y1="46" x2="244.2" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 242.3,49.8 242.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">150 km</text><line x1="250.5" y1="46" x2="250.5" y2="86.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,93 246.7,84.8 254.3,84.8" style="fill:currentColor;stroke:none"/><text x="264.5" y="73.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">50 km</text><line x1="109.5" y1="234" x2="246" y2="97.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,93 247.4,101.5 242,96.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="170.1" y="153.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A flight of 200 km north, 150 km east and 50 km south; the resultant is dashed.'),
('cb87d3ab-d78f-5d4e-b64d-d4ca8f500033', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 26, 26, 'A hiker walks 6.0 km on a bearing of 040° and then 4.0 km on a bearing of 130°. (The legs are at right angles.) Calculate the bearing of her final position from the start.', NULL, 2, 'numeric'::answer_type, '73.69', '°', false, NULL, false, NULL, 'Angle between first leg and resultant = tan⁻¹(4.0 ÷ 6.0) = 33.7°. Bearing = 40 + 33.7 = 73.7°. Mark scheme (4 marks). M1: right angle between legs. C1: angle. C1: add to 040°. A1: bearing = 73.7°.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg2edc37fa-t fg2edc37fa-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2edc37fa-t">Perpendicular legs</title><desc id="fg2edc37fa-d">A hike of 6.0 km on a bearing of 040° then 4.0 km on a bearing of 130°; the resultant is dashed.</desc><line x1="63.6" y1="217.3" x2="189.3" y2="67.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="193.3,62.7 191,71.4 185.2,66.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="117.7" y="131" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">6.0 km</text><line x1="193.3" y1="62.7" x2="291.6" y2="145.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,149.2 287.7,146.9 292.6,141" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="253.9" y="95.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 km</text><line x1="63.6" y1="217.3" x2="290.4" y2="151" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,149.2 289.7,155.1 287.5,147.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="176.1" y="169.8" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="63.6" cy="217.3" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A hike of 6.0 km on a bearing of 040° then 4.0 km on a bearing of 130°; the resultant is dashed.'),
('64f54a7b-8606-5906-9d3d-fb8e187a4927', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 27, 27, 'Two displacements of 3.0 m and 4.0 m have a resultant of 5.0 m. Calculate the angle between them.', NULL, 2, 'numeric'::answer_type, '90', '°', false, NULL, false, NULL, '5.0² = 3.0² + 4.0², so cos θ = (3.0² + 4.0² − 5.0²) ÷ (2 × 3.0 × 4.0) = 0. Then θ = cos⁻¹(0) = 90°. Mark scheme (3 marks). C1: Pythagoras holds. C1: right angle. A1: θ = 90°.', 3, NULL, NULL),
('b2a699d8-6363-557e-b14b-51a086cfe6c3', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 28, 28, 'A walker goes 3.0 km north-east and then 3.0 km north-west. Calculate the magnitude of the resultant.', NULL, 2, 'numeric'::answer_type, '4.243 km', 'km', false, NULL, false, NULL, 'The legs are perpendicular: s = √(3.0² + 3.0²) = 4.24 km due north. Mark scheme (3 marks). C1: perpendicular legs. C1: Pythagoras. A1: s = 4.24 km.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg11b8d5e4-t fg11b8d5e4-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg11b8d5e4-t">North-east then north-west</title><desc id="fg11b8d5e4-d">A walk of 3.0 km north-east then 3.0 km north-west; the resultant points due north.</desc><line x1="133" y1="234" x2="222.5" y2="144.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="227,140 223.9,148.5 218.5,143.1" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="189.9" y="196.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">3.0 km</text><line x1="227" y1="140" x2="137.5" y2="50.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="133,46 141.5,49.1 136.1,54.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="189.9" y="83.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 km</text><line x1="133" y1="234" x2="133" y2="52.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="133,46 136.8,54.2 129.2,54.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="147" y="140" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">s</text><circle cx="133" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A walk of 3.0 km north-east then 3.0 km north-west; the resultant points due north.'),
('1b1b124d-6d8d-5dd6-8c18-c6469a693591', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 29, 29, 'A student draws 4 cm north and 3 cm east to represent two displacements, and measures the resultant as 5 cm. What must she also measure?', NULL, 2, 'multiple_choice'::answer_type, 'The angle of the resultant (its direction)', NULL, false, NULL, false, NULL, 'A displacement needs a magnitude and a direction. Mark scheme (3 marks). C1: direction. C1: protractor. A1: C (The angle of the resultant (its direction)).', 3, NULL, NULL),
('4752fb1d-04d4-5b2a-bb05-b4fbed8ee757', '683a1a72-6900-4e3c-a063-dca54eb50d4a', '11e7164b-e47d-4b4d-8bad-1002c892ba20', 'a-level', '1.5', '9702 coursebook 1.5 · Combining displacements', 30, 30, 'A yacht has components of displacement 7.5 km east and 4.0 km south. Calculate the angle of its displacement south of east.', NULL, 2, 'numeric'::answer_type, '28.07', '°', false, NULL, false, NULL, 'θ = tan⁻¹(4.0 ÷ 7.5) = 28.1°. Mark scheme (3 marks). C1: tan θ. C1: value. A1: θ = 28.1°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgb3431eb3-t fgb3431eb3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb3431eb3-t">Displacement components</title><desc id="fgb3431eb3-d">Components of 7.5 km east and 4.0 km south drawn head to tail; the displacement is dashed.</desc><line x1="63.6" y1="77.9" x2="290.1" y2="77.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,77.9 288.3,81.7 288.3,74.1" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="63.9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">7.5 km</text><line x1="296.4" y1="77.9" x2="296.4" y2="195.8" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="296.4,202.1 292.6,193.9 300.2,193.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="310.4" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 km</text><line x1="63.6" y1="77.9" x2="290.9" y2="199.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="296.4,202.1 287.5,201.6 291,194.9" style="fill:var(--fig-muted,#6b7280)