INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('a1ec385e-138e-5e28-807c-ca92afb0e72a', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 1, 1, 'A boat heads straight across a river at 4.0 m s⁻¹ relative to the water. The current flows at 3.0 m s⁻¹. Calculate the boat''s resultant speed.', NULL, 1, 'numeric'::answer_type, '5', 'm s⁻¹', false, NULL, false, NULL, 'v = √(4.0² + 3.0²) = 5.0 m s⁻¹. Mark scheme (2 marks). C1: Pythagoras. A1: v = 5.0 m s⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg75869935-t fg75869935-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg75869935-t">Boat and current</title><desc id="fg75869935-d">The boat''s velocity of 4.0 m s⁻¹ across the river and the current''s 3.0 m s⁻¹ along it, added head to tail; the resultant is dashed.</desc><line x1="109.5" y1="234" x2="109.5" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="109.5,46 113.3,54.2 105.7,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="95.5" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">4.0 m s⁻¹</text><line x1="109.5" y1="46" x2="244.2" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 242.3,49.8 242.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 m s⁻¹</text><line x1="109.5" y1="234" x2="246.7" y2="51" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,46 248.6,54.8 242.6,50.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="168.8" y="131.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'The boat''s velocity of 4.0 m s⁻¹ across the river and the current''s 3.0 m s⁻¹ along it, added head to tail; the resultant is dashed.'),
('0695fc8f-2fab-5a6b-aaf6-29b0f91b902b', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 2, 2, 'A swimmer swims at 1.5 m s⁻¹ downstream in a river flowing at 0.5 m s⁻¹. What is her speed relative to the bank?', NULL, 1, 'multiple_choice'::answer_type, '2.0 m s⁻¹', NULL, false, NULL, false, NULL, 'Velocities in the same direction add. Mark scheme (1 mark). B1: C (2.0 m s⁻¹).', 1, NULL, NULL),
('e75c8306-0bde-519f-bbc8-3cbb7ce1ebf5', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 3, 3, 'The same swimmer (1.5 m s⁻¹ in still water) swims upstream against a 0.5 m s⁻¹ current. What is her speed relative to the bank?', NULL, 1, 'multiple_choice'::answer_type, '1.0 m s⁻¹', NULL, false, NULL, false, NULL, 'Opposite velocities subtract. Mark scheme (1 mark). B1: A (1.0 m s⁻¹).', 1, NULL, NULL),
('6b3d79c7-d1dc-5e07-aefa-140f4b099a15', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 4, 4, 'An aircraft flies north at 200 m s⁻¹ in a wind blowing east at 50 m s⁻¹. Calculate its resultant speed.', NULL, 1, 'numeric'::answer_type, '206.2', 'm s⁻¹', false, NULL, false, NULL, 'v = √(200² + 50²) = 206 m s⁻¹. Mark scheme (2 marks). C1: Pythagoras. A1: v = 206 m s⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg191a81ea-t fg191a81ea-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg191a81ea-t">Aircraft in a crosswind</title><desc id="fg191a81ea-d">An air velocity of 200 m s⁻¹ north plus a wind of 50 m s⁻¹ east; the resultant ground velocity is dashed.</desc><line x1="156.5" y1="234" x2="156.5" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="156.5,46 160.3,54.2 152.7,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="142.5" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">200 m s⁻¹</text><line x1="156.5" y1="46" x2="197.2" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="203.5,46 195.3,49.8 195.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">50 m s⁻¹</text><line x1="156.5" y1="234" x2="202" y2="52.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="203.5,46 205.2,54.8 197.8,53" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="166.4" y="136.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="156.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'An air velocity of 200 m s⁻¹ north plus a wind of 50 m s⁻¹ east; the resultant ground velocity is dashed.'),
('3a4f9852-3c72-50d1-9918-3db2b751f05f', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 5, 5, 'How are two velocities at right angles combined?', NULL, 1, 'multiple_choice'::answer_type, 'By vector addition: the resultant is the hypotenuse of the right-angled triangle', NULL, false, NULL, false, NULL, 'Use Pythagoras for the size and trigonometry for the angle. Mark scheme (1 mark). B1: D (By vector addition: the resultant is the hypotenuse of the right-angled triangle).', 1, NULL, NULL),
('00de020a-8b82-546e-a939-82acd5dee227', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 6, 6, 'A passenger walks forwards at 1.5 m s⁻¹ in a train moving at 30 m s⁻¹. Calculate her speed relative to the ground.', NULL, 1, 'numeric'::answer_type, '31.5', 'm s⁻¹', false, NULL, false, NULL, 'v = 30 + 1.5 = 31.5 m s⁻¹. Mark scheme (2 marks). C1: add, same direction. A1: v = 31.5 m s⁻¹.', 2, NULL, NULL),
('442315d8-e5f3-591a-b633-c9cb2e2fc25d', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 7, 7, 'A passenger walks towards the back of a train at 1.5 m s⁻¹ while the train moves forwards at 30 m s⁻¹. Calculate her velocity relative to the ground.', NULL, 1, 'numeric'::answer_type, '28.5', 'm s⁻¹', false, NULL, false, NULL, 'v = 30 − 1.5 = 28.5 m s⁻¹ forwards. Mark scheme (2 marks). C1: subtract, opposite. A1: v = 28.5 m s⁻¹.', 2, NULL, NULL),
('42f7f8d4-4dde-56e4-9c3c-82bd089ee730', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 8, 8, 'A boat crosses a river heading straight across. What effect does the current have?', NULL, 1, 'multiple_choice'::answer_type, 'It carries the boat downstream, so it lands further down the far bank', NULL, false, NULL, false, NULL, 'The current adds a velocity along the river. Mark scheme (1 mark). B1: B (It carries the boat downstream, so it lands further down the far bank).', 1, NULL, NULL),
('12689338-2987-50de-adcb-46abb9dec5a6', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 9, 9, 'A boat heads across a river at 3.0 m s⁻¹ while the current flows at 3.0 m s⁻¹. Calculate the angle between the boat''s resultant velocity and the bank.', NULL, 1, 'numeric'::answer_type, '45', '°', false, NULL, false, NULL, 'tan θ = 3.0 ÷ 3.0, so θ = tan⁻¹(3.0 ÷ 3.0) = 45°. Mark scheme (2 marks). C1: equal components. A1: θ = 45°.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fge52e3adf-t fge52e3adf-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fge52e3adf-t">Equal velocities</title><desc id="fge52e3adf-d">A boat velocity of 3.0 m s⁻¹ across the river plus a current of 3.0 m s⁻¹; the resultant is dashed with its angle θ to the bank.</desc><line x1="86" y1="234" x2="86" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,46 89.8,54.2 82.2,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="72" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">3.0 m s⁻¹</text><line x1="86" y1="46" x2="267.7" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="274,46 265.8,49.8 265.8,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 m s⁻¹</text><line x1="86" y1="234" x2="269.5" y2="50.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="274,46 270.9,54.5 265.5,49.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="170.1" y="130.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="86" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A boat velocity of 3.0 m s⁻¹ across the river plus a current of 3.0 m s⁻¹; the resultant is dashed with its angle θ to the bank.'),
('b58bf43c-38ff-5d4d-a76a-aa498376ede9', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 10, 10, 'Rain falls vertically at 8 m s⁻¹. A wind blows horizontally at 6 m s⁻¹. What is the speed of the raindrops?', NULL, 1, 'multiple_choice'::answer_type, '10 m s⁻¹', NULL, false, NULL, false, NULL, 'Resultant = √(8² + 6²) = 10 m s⁻¹. Mark scheme (1 mark). B1: C (10 m s⁻¹).', 1, NULL, NULL),
('370a283e-9721-5957-8733-bb9891494352', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 11, 11, 'A drone flies east at 12 m s⁻¹ in a wind blowing north at 5.0 m s⁻¹. Calculate its resultant speed.', NULL, 1, 'numeric'::answer_type, '13', 'm s⁻¹', false, NULL, false, NULL, 'v = √(12² + 5.0²) = 13 m s⁻¹. Mark scheme (2 marks). C1: Pythagoras. A1: v = 13 m s⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgcff3b933-t fgcff3b933-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgcff3b933-t">Drone in wind</title><desc id="fgcff3b933-d">A drone velocity of 12 m s⁻¹ east plus a wind of 5.0 m s⁻¹ north; the resultant is dashed.</desc><line x1="76.8" y1="183" x2="276.9" y2="183" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="283.2,183 275.1,186.8 275.1,179.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="197" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">12 m s⁻¹</text><line x1="283.2" y1="183" x2="283.2" y2="103.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="283.2,97 287,105.1 279.4,105.1" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="297.2" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">5.0 m s⁻¹</text><line x1="76.8" y1="183" x2="277.4" y2="99.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="283.2,97 277.2,103.6 274.2,96.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185.4" y="152.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="76.8" cy="183" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A drone velocity of 12 m s⁻¹ east plus a wind of 5.0 m s⁻¹ north; the resultant is dashed.'),
('c331acfb-043e-518b-9cab-dfb4008b0a40', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 12, 12, 'A plane flies into a headwind. What happens to its speed relative to the ground?', NULL, 1, 'multiple_choice'::answer_type, 'It is reduced by the wind speed', NULL, false, NULL, false, NULL, 'A headwind is opposite to the motion. Mark scheme (1 mark). B1: A (It is reduced by the wind speed).', 1, NULL, NULL),
('a510402c-6bf2-53be-b02a-5b1f66486e19', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 13, 13, 'A plane has an airspeed of 240 m s⁻¹ and flies into a 40 m s⁻¹ headwind. Calculate its ground speed.', NULL, 1, 'numeric'::answer_type, '200', 'm s⁻¹', false, NULL, false, NULL, 'v = 240 − 40 = 200 m s⁻¹. Mark scheme (2 marks). C1: subtract. A1: v = 200 m s⁻¹.', 2, NULL, NULL),
('fad2e8ff-2632-5b72-b0e8-b297884a2334', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 14, 14, 'A plane with airspeed 240 m s⁻¹ has a 40 m s⁻¹ tailwind. Calculate its ground speed.', NULL, 1, 'numeric'::answer_type, '280', 'm s⁻¹', false, NULL, false, NULL, 'v = 240 + 40 = 280 m s⁻¹. Mark scheme (2 marks). C1: add. A1: v = 280 m s⁻¹.', 2, NULL, NULL),
('06eb4646-3d75-5490-890b-576d2a0a3d41', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 15, 15, 'A person runs at 3 m s⁻¹ along the deck of a ship that moves at 3 m s⁻¹ in the opposite direction. What is the person''s velocity relative to the sea?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'The two velocities cancel. Mark scheme (1 mark). B1: D (Zero).', 1, NULL, NULL),
('0b5b9d70-c67b-5f6b-b5ba-a390b8f8f7ec', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 16, 16, 'A conveyor belt moves at 0.80 m s⁻¹. A box slides along it at 0.30 m s⁻¹ in the same direction relative to the belt. Calculate the box''s speed relative to the floor.', NULL, 1, 'numeric'::answer_type, '1.1', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.80 + 0.30 = 1.1 m s⁻¹. Mark scheme (1 mark). A1: v = 1.1 m s⁻¹.', 1, NULL, NULL),
('f6db0a2a-87b2-5fe0-98dd-dc6d57fd5e3d', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 17, 17, 'Which is the correct way to describe a velocity "relative to the water"?', NULL, 1, 'multiple_choice'::answer_type, 'The velocity an observer moving with the water would measure', NULL, false, NULL, false, NULL, 'Relative velocity depends on the observer. Mark scheme (1 mark). B1: B (The velocity an observer moving with the water would measure).', 1, NULL, NULL),
('03f0ac5b-b5a9-5c94-904f-c170228552f8', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 18, 18, 'A lift rises at 2.0 m s⁻¹. A toy dropped inside falls at 3.0 m s⁻¹ relative to the lift. Calculate the speed of the toy relative to the building.', NULL, 1, 'numeric'::answer_type, '1', 'm s⁻¹', false, NULL, false, NULL, 'Taking up as positive: v = 2.0 − 3.0 = −1.0 m s⁻¹, so its speed is 3.0 − 2.0 = 1.0 m s⁻¹ downwards. Mark scheme (2 marks). C1: combine with signs. A1: v = 1.0 m s⁻¹.', 2, NULL, NULL),
('cde0e504-e81d-5caf-a0da-6ca52902029a', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 19, 19, 'An escalator moves upwards at 0.60 m s⁻¹ and a woman walks up it at 0.90 m s⁻¹ relative to the steps. Calculate her speed relative to the building.', NULL, 1, 'numeric'::answer_type, '1.5', 'm s⁻¹', false, NULL, false, NULL, 'v = 0.60 + 0.90 = 1.5 m s⁻¹. Mark scheme (2 marks). C1: add, same direction. A1: v = 1.5 m s⁻¹.', 2, NULL, NULL),
('50d00739-5089-5ec3-b2ae-5ebd3c1fd1da', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 20, 20, 'A boat heads straight across a 60 m wide river at 2.0 m s⁻¹ relative to the water; the current flows at 1.5 m s⁻¹. Calculate the time to cross.', NULL, 2, 'numeric'::answer_type, '30', 's', false, NULL, false, NULL, 't = 60 ÷ 2.0 = 30 s (only the across component matters). Mark scheme (3 marks). C1: across component only. C1: value. A1: t = 30 s.', 3, NULL, NULL),
('eeca3feb-6b31-5001-a264-5f6abcacaaa1', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 21, 21, 'A boat heads straight across a 60 m wide river at 2.0 m s⁻¹ relative to the water; the current flows at 1.5 m s⁻¹. How far downstream does it land?', NULL, 2, 'numeric'::answer_type, '45', 'm', false, NULL, false, NULL, 't = 60 ÷ 2.0 = 30 s; drift = 1.5 × 30 = 45 m. Mark scheme (3 marks). C1: crossing time. C1: drift. A1: x = 45 m.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg2e878371-t fg2e878371-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2e878371-t">Crossing a river</title><desc id="fg2e878371-d">Velocity of 2.0 m s⁻¹ across a 60 m river plus a 1.5 m s⁻¹ current; the resultant velocity is dashed.</desc><line x1="109.5" y1="234" x2="109.5" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="109.5,46 113.3,54.2 105.7,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="95.5" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">2.0 m s⁻¹</text><line x1="109.5" y1="46" x2="244.2" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 242.3,49.8 242.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">1.5 m s⁻¹</text><line x1="109.5" y1="234" x2="246.7" y2="51" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,46 248.6,54.8 242.6,50.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="168.8" y="131.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Velocity of 2.0 m s⁻¹ across a 60 m river plus a 1.5 m s⁻¹ current; the resultant velocity is dashed.'),
('5b4a62e8-2c4a-5a7c-9778-0c15f623fc63', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 22, 22, 'A boat that moves at 5.0 m s⁻¹ in still water must travel straight across a river flowing at 3.0 m s⁻¹. At what angle to the straight-across direction, upstream, must it head?', NULL, 2, 'numeric'::answer_type, '36.87', '°', false, NULL, false, NULL, 'sin θ = 3.0 ÷ 5.0, θ = sin⁻¹(3.0 ÷ 5.0) = 36.9°. Mark scheme (3 marks). C1: upstream component cancels current. C1: sin θ. A1: θ = 36.9°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgf1caa8ad-t fgf1caa8ad-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf1caa8ad-t">Heading upstream</title><desc id="fgf1caa8ad-d">A boat heading upstream at 5.0 m s⁻¹ relative to the water plus a 3.0 m s⁻¹ current gives a resultant straight across (dashed).</desc><line x1="250.5" y1="234" x2="113.3" y2="51" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="109.5,46 117.4,50.2 111.4,54.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="168.8" y="148.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">5.0 m s⁻¹</text><line x1="109.5" y1="46" x2="244.2" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 242.3,49.8 242.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">3.0 m s⁻¹</text><line x1="250.5" y1="234" x2="250.5" y2="52.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,46 254.3,54.2 246.7,54.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="236.5" y="140" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="250.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A boat heading upstream at 5.0 m s⁻¹ relative to the water plus a 3.0 m s⁻¹ current gives a resultant straight across (dashed).'),
('1d1c2885-1756-5ec2-b751-de4d1e1bb87e', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 23, 23, 'A boat that moves at 5.0 m s⁻¹ in still water heads upstream at an angle so that it goes straight across a river flowing at 3.0 m s⁻¹. Calculate its speed across the river.', NULL, 2, 'numeric'::answer_type, '4', 'm s⁻¹', false, NULL, false, NULL, 'v = √(5.0² − 3.0²) = 4.0 m s⁻¹. Mark scheme (3 marks). C1: Pythagoras with hypotenuse 5.0. C1: value. A1: v = 4.0 m s⁻¹.', 3, NULL, NULL),
('29fb6356-d01b-565f-9636-3c8ef298215e', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 24, 24, 'A plane heads due north at 180 m s⁻¹ while the wind blows from the west at 40 m s⁻¹. Calculate the angle of its track east of north.', NULL, 2, 'numeric'::answer_type, '12.53', '°', false, NULL, false, NULL, 'θ = tan⁻¹(40 ÷ 180) = 12.5°. Mark scheme (3 marks). C1: wind from west blows east. C1: tan θ. A1: θ = 12.5°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgac800586-t fgac800586-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgac800586-t">Wind from the west</title><desc id="fgac800586-d">An air velocity of 180 m s⁻¹ north plus a wind of 40 m s⁻¹ towards the east; the track is dashed with the angle θ east of north.</desc><line x1="159.1" y1="234" x2="159.1" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="159.1,46 162.9,54.2 155.3,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="145.1" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">180 m s⁻¹</text><line x1="159.1" y1="46" x2="194.6" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200.9,46 192.7,49.8 192.7,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">40 m s⁻¹</text><line x1="159.1" y1="234" x2="199.5" y2="52.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="200.9,46 202.8,54.8 195.4,53.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="166.3" y="137" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="159.1" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="159.1" y1="234" x2="159.1" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><path d="M159.1,204 A30,30 0 0,1 165.6,204.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="163.7" y="192.3" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ</text><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'An air velocity of 180 m s⁻¹ north plus a wind of 40 m s⁻¹ towards the east; the track is dashed with the angle θ east of north.'),
('06c77c09-fcc4-5333-b16d-776794141eb9', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 25, 25, 'A wind "from the west" acts on a plane. In which direction does it push the plane?', NULL, 2, 'multiple_choice'::answer_type, 'Towards the east', NULL, false, NULL, false, NULL, 'Winds are named by where they come from. Mark scheme (3 marks). C1: from the west. C1: blows east. A1: C (Towards the east).', 3, NULL, NULL),
('e4c26e39-a357-5155-bedd-b2a1c1da046e', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 26, 26, 'Rain falls vertically at 6.0 m s⁻¹. A cyclist rides at 4.0 m s⁻¹. At what angle to the vertical does the rain appear to fall, as seen by the cyclist?', NULL, 2, 'numeric'::answer_type, '33.69', '°', false, NULL, false, NULL, 'θ = tan⁻¹(4.0 ÷ 6.0) = 33.7°. Mark scheme (3 marks). C1: relative velocity. C1: tan θ. A1: θ = 33.7°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg757f5ed5-t fg757f5ed5-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg757f5ed5-t">Rain seen by a cyclist</title><desc id="fg757f5ed5-d">The rain''s velocity of 6.0 m s⁻¹ downwards plus the reversed cyclist velocity of 4.0 m s⁻¹ gives the velocity of the rain relative to the cyclist (dashed).</desc><line x1="242.7" y1="46" x2="242.7" y2="227.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="242.7,234 238.9,225.8 246.5,225.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="256.7" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">6.0 m s⁻¹</text><line x1="242.7" y1="234" x2="123.6" y2="234" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="117.3,234 125.5,230.2 125.5,237.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="248" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 m s⁻¹</text><line x1="242.7" y1="46" x2="120.8" y2="228.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="117.3,234 118.7,225.1 125,229.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="191.6" y="147.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="242.7" cy="46" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'The rain''s velocity of 6.0 m s⁻¹ downwards plus the reversed cyclist velocity of 4.0 m s⁻¹ gives the velocity of the rain relative to the cyclist (dashed).'),
('34ca9de0-1ad9-57db-a72e-9a3f235706f1', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 27, 27, 'A ball is thrown horizontally at 8.0 m s⁻¹ from a truck moving at 12 m s⁻¹ in the same direction. Calculate the ball''s horizontal speed relative to the road.', NULL, 2, 'numeric'::answer_type, '20', 'm s⁻¹', false, NULL, false, NULL, 'v = 12 + 8.0 = 20 m s⁻¹. Mark scheme (3 marks). C1: add velocities. C1: value. A1: v = 20 m s⁻¹.', 3, NULL, NULL),
('28677863-9a53-53e3-8542-41106f43f839', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 28, 28, 'A ball is thrown sideways at 8.0 m s⁻¹, at right angles to the motion of a truck moving at 12 m s⁻¹. Calculate the ball''s horizontal speed relative to the road.', NULL, 2, 'numeric'::answer_type, '14.42', 'm s⁻¹', false, NULL, false, NULL, 'v = √(12² + 8.0²) = 14.4 m s⁻¹. Mark scheme (3 marks). C1: right angles. C1: Pythagoras. A1: v = 14.4 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgbc19856b-t fgbc19856b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbc19856b-t">Ball thrown from a truck</title><desc id="fgbc19856b-d">The truck''s velocity of 12 m s⁻¹ plus the ball''s sideways 8.0 m s⁻¹; the ball''s resultant velocity is dashed.</desc><line x1="76.8" y1="208.8" x2="276.9" y2="208.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="283.2,208.8 275.1,212.6 275.1,205" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="222.8" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">12 m s⁻¹</text><line x1="283.2" y1="208.8" x2="283.2" y2="77.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="283.2,71.2 287,79.3 279.4,79.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="297.2" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">8.0 m s⁻¹</text><line x1="76.8" y1="208.8" x2="278" y2="74.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="283.2,71.2 278.6,78.9 274.3,72.5" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="187.8" y="151.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="76.8" cy="208.8" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'The truck''s velocity of 12 m s⁻¹ plus the ball''s sideways 8.0 m s⁻¹; the ball''s resultant velocity is dashed.'),
('7a4d5af9-598b-56db-aa3b-cb424fd524b7', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 29, 29, 'A swimmer who can swim at 1.2 m s⁻¹ heads straight across a river 48 m wide flowing at 0.90 m s⁻¹. Calculate the distance she actually travels relative to the bank.', NULL, 2, 'numeric'::answer_type, '60', 'm', false, NULL, false, NULL, 't = 48 ÷ 1.2 = 40 s; drift = 0.90 × 40 = 36 m; distance = √(48² + 36²) = 60.0 m. Mark scheme (4 marks). C1: time. C1: drift. C1: resultant. A1: d = 60 m.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg25290ed7-t fg25290ed7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg25290ed7-t">Swimmer and current</title><desc id="fg25290ed7-d">A swimmer''s 1.2 m s⁻¹ across a 48 m river plus a 0.90 m s⁻¹ current; the resultant is dashed.</desc><line x1="109.5" y1="234" x2="109.5" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="109.5,46 113.3,54.2 105.7,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="95.5" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">1.2 m s⁻¹</text><line x1="109.5" y1="46" x2="244.2" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 242.3,49.8 242.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">0.90 m s⁻¹</text><line x1="109.5" y1="234" x2="246.7" y2="51" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,46 248.6,54.8 242.6,50.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="168.8" y="131.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A swimmer''s 1.2 m s⁻¹ across a 48 m river plus a 0.90 m s⁻¹ current; the resultant is dashed.'),
('f39c6ed6-4ca8-5f93-9f41-beeb119ebf45', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 30, 30, 'Why does heading a boat upstream at an angle increase the time to cross a river?', NULL, 2, 'multiple_choice'::answer_type, 'Part of its velocity is used to cancel the current, leaving a smaller component across the river', NULL, false, NULL, false, NULL, 'Only the across component carries it over. Mark scheme (3 marks). C1: component cancels current. C1: smaller across component. A1: A (Part of its velocity is used to cancel the current, leaving a smaller component across the river).', 3, NULL, NULL),
('bdfb3627-69c9-5a04-85ff-207bfabe9a80', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 31, 31, 'A plane must fly due east at a ground speed of 250 m s⁻¹ while a wind blows from the south at 30 m s⁻¹. Calculate the airspeed it needs.', NULL, 2, 'numeric'::answer_type, '251.8', 'm s⁻¹', false, NULL, false, NULL, 'Air velocity = ground velocity − wind: 250 east and 30 south. v = √(250² + 30²) = 252 m s⁻¹. Mark scheme (3 marks). C1: subtract wind. C1: Pythagoras. A1: v = 252 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg6ae701a2-t fg6ae701a2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6ae701a2-t">Allowing for wind</title><desc id="fg6ae701a2-d">The air velocity (dashed) plus a wind of 30 m s⁻¹ towards the north must give 250 m s⁻¹ due east.</desc><line x1="94.2" y1="129.7" x2="259.6" y2="149.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="265.8,150.3 257.3,153.1 258.2,145.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="178.3" y="153.9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">air velocity</text><line x1="265.8" y1="150.3" x2="265.8" y2="136" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="265.8,129.7 269.6,137.9 262,137.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="279.8" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">30 m s⁻¹</text><line x1="94.2" y1="129.7" x2="259.5" y2="129.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="265.8,129.7 257.7,133.5 257.7,125.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="143.7" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">250 m s⁻¹</text><circle cx="94.2" cy="129.7" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'The air velocity (dashed) plus a wind of 30 m s⁻¹ towards the north must give 250 m s⁻¹ due east.'),
('4ddc16ff-c213-5767-b532-e2be74996456', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 32, 32, 'A man walks across the deck of a ferry at 1.4 m s⁻¹, at right angles to its motion at 4.8 m s⁻¹. Calculate his speed relative to the water.', NULL, 2, 'numeric'::answer_type, '5', 'm s⁻¹', false, NULL, false, NULL, 'v = √(4.8² + 1.4²) = 5.0 m s⁻¹. Mark scheme (3 marks). C1: perpendicular velocities. C1: value. A1: v = 5.0 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg250bf9d5-t fg250bf9d5-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg250bf9d5-t">Walking on a ferry</title><desc id="fg250bf9d5-d">The ferry''s 4.8 m s⁻¹ plus the man''s 1.4 m s⁻¹ across the deck; his resultant velocity is dashed.</desc><line x1="76.8" y1="170.1" x2="276.9" y2="170.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="283.2,170.1 275.1,173.9 275.1,166.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="184.1" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">4.8 m s⁻¹</text><line x1="283.2" y1="170.1" x2="283.2" y2="116.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="283.2,109.9 287,118 279.4,118" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="297.2" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">1.4 m s⁻¹</text><line x1="76.8" y1="170.1" x2="277.2" y2="111.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="283.2,109.9 276.5,115.8 274.3,108.5" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="183.9" y="153.4" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="76.8" cy="170.1" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'The ferry''s 4.8 m s⁻¹ plus the man''s 1.4 m s⁻¹ across the deck; his resultant velocity is dashed.'),
('da726023-7701-5405-8644-c93009950ba3', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 33, 33, 'A river flows at 2.5 m s⁻¹. A boat heads directly upstream at 6.0 m s⁻¹ relative to the water. How long does it take to travel 700 m upstream?', NULL, 2, 'numeric'::answer_type, '200', 's', false, NULL, false, NULL, 'Ground speed = 6.0 − 2.5 = 3.5 m s⁻¹; t = 700 ÷ 3.5 = 200 s. Mark scheme (3 marks). C1: relative speed. C1: t = d/v. A1: t = 200 s.', 3, NULL, NULL),
('3fad3fda-a9ee-5938-8aaa-b58db654ffe7', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 34, 34, 'A kite moves at 3.0 m s⁻¹ horizontally and 4.0 m s⁻¹ vertically. Calculate the angle of its velocity above the horizontal.', NULL, 2, 'numeric'::answer_type, '53.13', '°', false, NULL, false, NULL, 'θ = tan⁻¹(4.0 ÷ 3.0) = 53.1°. Mark scheme (3 marks). C1: tan θ = vertical/horizontal. C1: value. A1: θ = 53.1°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg9362a979-t fg9362a979-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9362a979-t">Kite velocity</title><desc id="fg9362a979-d">Velocity components of 3.0 m s⁻¹ horizontally and 4.0 m s⁻¹ vertically; the velocity is dashed with its angle θ above the horizontal.</desc><line x1="109.5" y1="234" x2="244.2" y2="234" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,234 242.3,237.8 242.3,230.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="248" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">3.0 m s⁻¹</text><line x1="250.5" y1="234" x2="250.5" y2="52.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="250.5,46 254.3,54.2 246.7,54.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="264.5" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">4.0 m s⁻¹</text><line x1="109.5" y1="234" x2="246.7" y2="51" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="250.5,46 248.6,54.8 242.6,50.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="191.2" y="148.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="109.5" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="109.5" y1="234" x2="153.5" y2="234" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><path d="M139.5,234 A30,30 0 0,0 127.5,210" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="147.1" y="215.2" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">θ</text></svg>', 'Velocity components of 3.0 m s⁻¹ horizontally and 4.0 m s⁻¹ vertically; the velocity is dashed with its angle θ above the horizontal.'),
('5d616827-eb94-56d4-885a-c3c2f6037743', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 35, 35, 'Two cars approach each other head-on, at 20 m s⁻¹ and 25 m s⁻¹. What is the speed of one relative to the other?', NULL, 2, 'multiple_choice'::answer_type, '45 m s⁻¹', NULL, false, NULL, false, NULL, 'Relative velocity = v₁ − v₂ with opposite signs: 20 − (−25). Mark scheme (3 marks). C1: opposite directions. C1: magnitudes add. A1: D (45 m s⁻¹).', 3, NULL, NULL),
('117ec412-554d-5cc7-8cd2-14baa28e7d6f', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 36, 36, 'A velocity of 15 m s⁻¹ is directed at 25° above the horizontal. Calculate its horizontal component.', NULL, 2, 'numeric'::answer_type, '13.59', 'm s⁻¹', false, NULL, false, NULL, 'v_x = 15 cos 25° = 13.6 m s⁻¹. Mark scheme (3 marks). C1: cosine. C1: value. A1: v_x = 13.6 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgf41f13cf-t fgf41f13cf-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf41f13cf-t">Velocity components</title><desc id="fgf41f13cf-d">A velocity of 15 m s⁻¹ at 25° above the horizontal (dashed) with its horizontal and vertical components.</desc><line x1="73.2" y1="189.8" x2="280.5" y2="189.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="286.8,189.8 278.7,193.6 278.7,186" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="203.8" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)"></text><line x1="286.8" y1="189.8" x2="286.8" y2="96.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="286.8,90.2 290.6,98.3 283,98.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="300.8" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)"></text><line x1="73.2" y1="189.8" x2="281.1" y2="92.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="286.8,90.2 281.1,97.1 277.8,90.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="185.9" y="152.7" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">15 m s⁻¹</text><circle cx="73.2" cy="189.8" r="3.4" style="fill:currentColor;stroke:none"/><line x1="73.2" y1="189.8" x2="117.2" y2="189.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><path d="M103.2,189.8 A30,30 0 0,0 100.3,177.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="114.2" y="180.7" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">25°</text></svg>', 'A velocity of 15 m s⁻¹ at 25° above the horizontal (dashed) with its horizontal and vertical components.'),
('31fb9a42-8c7a-5eae-bc0d-a121c9e1daf9', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 37, 37, 'What is the upward part of a velocity of 15 m s⁻¹ aimed 25° above the horizontal?', NULL, 2, 'numeric'::answer_type, '6.339', 'm s⁻¹', false, NULL, false, NULL, 'v_y = 15 sin 25° = 6.34 m s⁻¹. Mark scheme (3 marks). C1: sine. C1: value. A1: v_y = 6.34 m s⁻¹.', 3, NULL, NULL),
('0cd7943b-0018-5d7f-8563-0eb10871f425', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 38, 38, 'A walkway carries people forwards at 0.75 m s⁻¹. A child runs backwards along it at 2.0 m s⁻¹ relative to the walkway. How long does the child take to move 25 m relative to the ground?', NULL, 2, 'numeric'::answer_type, '20', 's', false, NULL, false, NULL, 'v = 2.0 − 0.75 = 1.25 m s⁻¹ backwards; t = 25 ÷ 1.25 = 20 s. Mark scheme (3 marks). C1: relative velocity. C1: t = d/v. A1: t = 20 s.', 3, NULL, NULL),
('ab5e9f31-722b-5c7d-870a-984d30336bac', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 39, 39, 'A canoeist paddles north at 2.4 m s⁻¹ relative to the water in a current flowing east at 0.70 m s⁻¹. Calculate her speed relative to the bank.', NULL, 2, 'numeric'::answer_type, '2.5', 'm s⁻¹', false, NULL, false, NULL, 'v = √(2.4² + 0.70²) = 2.5 m s⁻¹. Mark scheme (3 marks). C1: perpendicular. C1: Pythagoras. A1: v = 2.5 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg38c70462-t fg38c70462-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg38c70462-t">Canoe and current</title><desc id="fg38c70462-d">A paddling velocity of 2.4 m s⁻¹ north plus a 0.70 m s⁻¹ current east; the resultant is dashed.</desc><line x1="152.6" y1="234" x2="152.6" y2="52.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="152.6,46 156.4,54.2 148.8,54.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="138.6" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">2.4 m s⁻¹</text><line x1="152.6" y1="46" x2="201.1" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="207.4,46 199.3,49.8 199.3,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">0.70 m s⁻¹</text><line x1="152.6" y1="234" x2="205.7" y2="52" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="207.4,46 208.8,54.9 201.5,52.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="166.6" y="136.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="152.6" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'A paddling velocity of 2.4 m s⁻¹ north plus a 0.70 m s⁻¹ current east; the resultant is dashed.'),
('9c937ff2-14fd-5ee6-b525-022e25a04d37', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 40, 40, 'A plane points due north but its track over the ground is north-east. What does this show about the wind?', NULL, 2, 'multiple_choice'::answer_type, 'It blows towards the east with a speed equal to the plane''s airspeed', NULL, false, NULL, false, NULL, 'A 45° track needs equal north and east components. Mark scheme (3 marks). C1: eastward wind. C1: equal components. A1: B (It blows towards the east with a speed equal to the plane''s airspeed).', 3, NULL, NULL),
('bf8fbd0e-b437-5f3c-b232-31e002fc3a32', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 41, 41, 'A plane with airspeed 220 m s⁻¹ heads due north. A wind of 50 m s⁻¹ blows towards the north-east. (a) Find the east and north components of the wind. (b) Calculate the ground speed.', NULL, 3, 'numeric'::answer_type, '257.8', 'm s⁻¹', false, NULL, false, NULL, '(a) East = 50 sin 45° = 35.36; north = 50 cos 45° = 35.36 m s⁻¹. (b) v = √(35.36² + (220 + 35.36)²) = 258 m s⁻¹. Mark scheme (5 marks). C1: wind components. M1: add north components. C1: Pythagoras. C1: value. A1: v = 258 m s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg563109fa-t fg563109fa-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg563109fa-t">North-east wind</title><desc id="fg563109fa-d">An air velocity of 220 m s⁻¹ north plus a 50 m s⁻¹ wind towards the north-east; the ground velocity is dashed.</desc><line x1="167" y1="234" x2="167" y2="78.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="167,72 170.8,80.2 163.2,80.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="153" y="157" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">220 m s⁻¹</text><line x1="167" y1="72" x2="188.6" y2="50.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="193,46 189.9,54.5 184.6,49.1" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="170.1" y="49.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">50 m s⁻¹</text><line x1="167" y1="234" x2="192.2" y2="52.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="193,46 195.7,54.6 188.1,53.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="166.1" y="138.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="167" cy="234" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'An air velocity of 220 m s⁻¹ north plus a 50 m s⁻¹ wind towards the north-east; the ground velocity is dashed.'),
('bd81ef22-a936-52e7-bc70-06d5a915f2a5', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 42, 42, 'A boat crosses a river 120 m wide. It can move at 4.0 m s⁻¹ in still water and the current is 2.0 m s⁻¹. It is steered to land directly opposite. (a) Calculate the angle upstream at which it must head. (b) Calculate its speed across. (c) Calculate the crossing time.', NULL, 3, 'numeric'::answer_type, '34.64', 's', false, NULL, false, NULL, '(a) sin θ = 2.0 ÷ 4.0, θ = sin⁻¹(2.0 ÷ 4.0) = 30°. (b) v = √(4.0² − 2.0²) = 3.464 m s⁻¹. (c) t = 120 ÷ 3.464 = 34.6 s. Mark scheme (6 marks). M1: upstream component = current. C1: angle. C1: across speed. M1: t = width/speed. C1: value. A1: t = 34.6 s.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg9e99f75a-t fg9e99f75a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9e99f75a-t">Landing directly opposite</title><desc id="fg9e99f75a-d">A heading of 4.0 m s⁻¹ angled upstream plus a 2.0 m s⁻¹ current gives a resultant straight across (dashed).</desc><line x1="234.3" y1="234" x2="128.9" y2="51.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="125.7,46 133.1,51.2 126.5,55" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="167.9" y="147" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">4.0 m s⁻¹</text><line x1="125.7" y1="46" x2="228" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="234.3,46 226.1,49.8 226.1,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">2.0 m s⁻¹</text><line x1="234.3" y1="234" x2="234.3" y2="52.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="234.3,46 238.1,54.2 230.5,54.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="220.3" y="140" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="234.3" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A heading of 4.0 m s⁻¹ angled upstream plus a 2.0 m s⁻¹ current gives a resultant straight across (dashed).'),
('2f91ff73-6c5a-5015-af25-523ec50f4937', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 43, 43, 'A pilot wants to fly due east. The plane''s airspeed is 150 m s⁻¹ and a wind blows due north at 30 m s⁻¹. (a) Calculate the angle south of east at which the pilot must head. (b) Calculate the ground speed.', NULL, 3, 'numeric'::answer_type, '147', 'm s⁻¹', false, NULL, false, NULL, '(a) sin θ = 30 ÷ 150, θ = sin⁻¹(30 ÷ 150) = 11.5°. (b) v = √(150² − 30²) = 147 m s⁻¹. Mark scheme (5 marks). M1: southward component cancels wind. C1: angle. M1: Pythagoras. C1: value. A1: v = 147 m s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgeec45c21-t fgeec45c21-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgeec45c21-t">Correcting for wind</title><desc id="fgeec45c21-d">An air velocity of 150 m s⁻¹ angled south of east plus a 30 m s⁻¹ wind north gives a ground velocity due east (dashed).</desc><line x1="79.9" y1="119.6" x2="273.9" y2="159.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="280.1,160.4 271.4,162.5 272.9,155.1" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="177.2" y="153.7" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">150 m s⁻¹</text><line x1="280.1" y1="160.4" x2="280.1" y2="125.9" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="280.1,119.6 283.9,127.7 276.3,127.7" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="294.1" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">30 m s⁻¹</text><line x1="79.9" y1="119.6" x2="273.8" y2="119.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="280.1,119.6 272,123.4 272,115.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="180" y="133.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="79.9" cy="119.6" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'An air velocity of 150 m s⁻¹ angled south of east plus a 30 m s⁻¹ wind north gives a ground velocity due east (dashed).'),
('1bec84d4-1d85-5a83-b364-0be04373052c', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 44, 44, 'A swimmer heads at 30° upstream of straight across a river 40 m wide. She swims at 1.6 m s⁻¹ in still water; the current is 0.50 m s⁻¹. (a) Find her velocity components across and along the river. (b) Calculate the crossing time. (c) Calculate where she lands relative to the point opposite.', NULL, 3, 'numeric'::answer_type, '8.66', 'm', false, NULL, false, NULL, '(a) Across: 1.6 cos 30° = 1.386 m s⁻¹; upstream: 1.6 sin 30° − 0.50 = 0.30 m s⁻¹. (b) t = 40 ÷ 1.386 = 28.87 s. (c) x = 0.30 × 28.87 = 8.66 m upstream. Mark scheme (6 marks). C1: across component. C1: along component. C1: time. M1: displacement along. C1: value. A1: x = 8.66 m.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg6af0c5a0-t fg6af0c5a0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6af0c5a0-t">Swimming upstream at an angle</title><desc id="fg6af0c5a0-d">A swimmer''s 1.6 m s⁻¹ at 30° upstream of straight across plus a 0.50 m s⁻¹ current; the resultant is dashed.</desc><line x1="234.3" y1="234" x2="128.9" y2="51.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="125.7,46 133.1,51.2 126.5,55" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="167.9" y="147" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">1.6 m s⁻¹</text><line x1="125.7" y1="46" x2="187.3" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="193.6,46 185.4,49.8 185.4,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="159.6" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">0.50 m s⁻¹</text><line x1="234.3" y1="234" x2="194.9" y2="52.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="193.6,46 199,53.2 191.6,54.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="200.2" y="143" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="234.3" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'A swimmer''s 1.6 m s⁻¹ at 30° upstream of straight across plus a 0.50 m s⁻¹ current; the resultant is dashed.'),
('7afe3292-2f70-5510-8199-86aa9293aab6', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 45, 45, 'Raindrops fall vertically at 7.0 m s⁻¹. To a passenger in a car, they appear to fall at 60° to the vertical. (a) Draw the relative-velocity triangle. (b) Calculate the speed of the car.', NULL, 3, 'numeric'::answer_type, '12.12', 'm s⁻¹', false, NULL, false, NULL, '(a) Rain relative to car = rain velocity − car velocity. (b) tan 60° = v ÷ 7.0, v = 7.0 × tan 60° = 12.1 m s⁻¹. Mark scheme (5 marks). B1: relative velocity triangle. M1: tan 60° = v/7.0. C1: rearrange. C1: value. A1: v = 12.1 m s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgbffdce96-t fgbffdce96-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbffdce96-t">Rain seen from a car</title><desc id="fgbffdce96-d">Rain falling at 7.0 m s⁻¹ plus the reversed car velocity gives a relative velocity at 60° to the vertical (dashed).</desc><line x1="205.4" y1="125.4" x2="205.4" y2="148.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="205.4,154.6 201.6,146.5 209.2,146.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="219.4" y="144" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">7.0 m s⁻¹</text><line x1="205.4" y1="154.6" x2="160.9" y2="154.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="154.6,154.6 162.8,150.8 162.8,158.4" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="180" y="168.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">car velocity reversed</text><line x1="205.4" y1="125.4" x2="160.1" y2="151.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="154.6,154.6 159.8,147.3 163.6,153.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="187" y="152.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="205.4" cy="125.4" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Rain falling at 7.0 m s⁻¹ plus the reversed car velocity gives a relative velocity at 60° to the vertical (dashed).'),
('470dc2af-b28c-5422-913c-8a3792a8aedb', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 46, 46, 'A ship sails north at 8.0 m s⁻¹. A sailor runs across the deck from the west side to the east side at 3.0 m s⁻¹, while the sea current flows south at 1.5 m s⁻¹. (a) Find the sailor''s north and east velocity components relative to the sea bed. (b) Calculate his speed relative to the sea bed.', NULL, 3, 'numeric'::answer_type, '7.159', 'm s⁻¹', false, NULL, false, NULL, '(a) North: 8.0 − 1.5 = 6.5 m s⁻¹; east: 3.0 m s⁻¹. (b) v = √(6.5² + 3.0²) = 7.16 m s⁻¹. Mark scheme (6 marks). C1: north component. C1: east component. M1: Pythagoras. C1: substitution. C1: value. A1: v = 7.16 m s⁻¹.', 6, NULL, NULL),
('aaee5452-41bd-5a18-8cd7-480d6adf40cb', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 47, 47, 'A ferry travels at 6.0 m s⁻¹ relative to the water, heading 40° upstream from straight across. The current is 2.5 m s⁻¹. (a) Find the components of its velocity relative to the bank. (b) Calculate its speed relative to the bank.', NULL, 3, 'numeric'::answer_type, '4.792', 'm s⁻¹', false, NULL, false, NULL, '(a) Across: 6.0 cos 40° = 4.596; upstream: 6.0 sin 40° − 2.5 = 1.357 m s⁻¹. (b) v = √(4.596² + 1.357²) = 4.79 m s⁻¹. Mark scheme (5 marks). C1: across. C1: along. M1: Pythagoras. C1: value. A1: v = 4.79 m s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fg68f864eb-t fg68f864eb-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg68f864eb-t">Ferry heading upstream</title><desc id="fg68f864eb-d">The ferry''s 6.0 m s⁻¹ at 40° upstream of straight across plus a 2.5 m s⁻¹ current; the resultant is dashed.</desc><line x1="258.9" y1="234" x2="105.2" y2="50.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="101.1,46 109.3,49.8 103.5,54.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="169.3" y="149" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">6.0 m s⁻¹</text><line x1="101.1" y1="46" x2="197.1" y2="46" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="203.4,46 195.2,49.8 195.2,42.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="152.3" y="32" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">2.5 m s⁻¹</text><line x1="258.9" y1="234" x2="205.2" y2="52" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="203.4,46 209.3,52.7 202,54.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="217.7" y="144" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="258.9" cy="234" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'The ferry''s 6.0 m s⁻¹ at 40° upstream of straight across plus a 2.5 m s⁻¹ current; the resultant is dashed.'),
('521c3674-c6ca-54da-9601-116183309f88', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 48, 48, 'An aircraft flies from A to B, 600 km due north, and back. Its airspeed is 250 km h⁻¹ and a wind blows from the east at 50 km h⁻¹. (a) Calculate its ground speed when heading to fly due north. (b) Calculate the time for the round trip, in hours.', NULL, 3, 'numeric'::answer_type, '4.899', 'h', false, NULL, false, NULL, '(a) v = √(250² − 50²) = 244.9 km h⁻¹ (the same both ways). (b) t = 1200 ÷ 244.9 = 4.90 h. Mark scheme (6 marks). M1: crosswind cancelled. C1: ground speed. B1: same both ways. M1: total distance ÷ speed. C1: value. A1: t = 4.90 h.', 6, NULL, NULL),
('d9b6bc0a-a47d-5774-a31f-a52b64adb5a0', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 49, 49, 'Two ships leave a port at the same time: P sails north at 10 m s⁻¹ and Q sails east at 7.5 m s⁻¹. (a) Calculate the speed of Q relative to P. (b) Calculate the distance between them after 20 minutes, in km.', NULL, 3, 'numeric'::answer_type, '15 km', 'km', false, NULL, false, NULL, '(a) v = √(10² + 7.5²) = 12.5 m s⁻¹. (b) d = 12.5 × 1200 = 15 000 m. In km: 15 000 ÷ 1000 = 15. Mark scheme (5 marks). M1: relative velocity. C1: value. M1: d = vt. C1: km. A1: d = 15 km.', 5, NULL, NULL),
('47233f87-7b8c-5076-b19a-585c83d8b15e', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 50, 50, 'A drone flies with airspeed 18 m s⁻¹, heading due east, in a wind of 6.0 m s⁻¹ blowing towards the south-west. (a) Find the wind''s east and north components. (b) Calculate the drone''s ground speed.', NULL, 3, 'numeric'::answer_type, '14.4', 'm s⁻¹', false, NULL, false, NULL, '(a) East: −6.0 cos 45° = −4.243; north: −6.0 sin 45° = −4.243 m s⁻¹. (b) v = √((18 − 4.243)² + 4.243²) = 14.4 m s⁻¹. Mark scheme (5 marks). C1: wind components. M1: add to airspeed. C1: Pythagoras. C1: value. A1: v = 14.4 m s⁻¹.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 280" role="img" aria-labelledby="fgfa29cd34-t fgfa29cd34-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgfa29cd34-t">Drone against a south-west wind</title><desc id="fgfa29cd34-d">An air velocity of 18 m s⁻¹ east plus a 6.0 m s⁻¹ wind towards the south-west; the ground velocity is dashed.</desc><line x1="76.8" y1="115.7" x2="276.9" y2="115.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="283.2,115.7 275.1,119.5 275.1,111.9" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="180" y="101.7" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">18 m s⁻¹</text><line x1="283.2" y1="115.7" x2="239" y2="159.9" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="234.6,164.3 237.7,155.9 243,161.3" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="268.8" y="149.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">6.0 m s⁻¹</text><line x1="76.8" y1="115.7" x2="228.6" y2="162.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="234.6,164.3 225.7,165.6 227.9,158.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="159.8" y="126.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v</text><circle cx="76.8" cy="115.7" r="3.4" style="fill:currentColor;stroke:none"/><line x1="338" y1="50" x2="338" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="338,18 341,24.3 335,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="338" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'An air velocity of 18 m s⁻¹ east plus a 6.0 m s⁻¹ wind towards the south-west; the ground velocity is dashed.'),
('1f1e4802-3c8d-50dd-9d6d-79b04b8d6768', '4653a171-76f9-4b44-bc1d-19802787195f', '0e10f0fa-b4fd-4e02-beba-8c15b05746c1', 'a-level', '1.6', '9702 coursebook 1.6 · Combining velocities', 51, 51, 'A boat moves at 3.0 m s⁻¹ in still water and crosses a river 90 m wide with a current of 1.8 m s⁻¹, heading straight across. (a) Calculate the crossing time. (b) Calculate how far downstream it lands.', NULL, 3, 'numeric'::answer_type, '54', 'm', false, NULL, false, NULL, '(a) t = 90 ÷ 3.0 = 30 s. (b) x = 1.8 × 30 = 54 m. Mark scheme (5 marks). M1: across component only. C1: time. M1: drift = current × time. C1: value. A1: x = 54 m.', 5, NULL, NULL)
