INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('2480887d-a869-5bf4-828e-22d5182db996', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 1, 1, 'A ball moving at 6.0 m s⁻¹ to the right hits a wall and rebounds at 4.0 m s⁻¹ to the left. Calculate the magnitude of its change in velocity.', NULL, 1, 'numeric'::answer_type, '10', 'm s⁻¹', false, NULL, false, NULL, 'Taking right as positive: Δv = −4.0 − 6.0 = −10 m s⁻¹, so the magnitude is 4.0 + 6.0 = 10 m s⁻¹. Mark scheme (2 marks). C1: signs for directions. A1: Δv = 10 m s⁻¹.', 2, NULL, NULL),
('c74964c4-23c7-5613-bf5e-9d9d10e4d8b4', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 2, 2, 'How is the change in velocity Δv found?', NULL, 1, 'multiple_choice'::answer_type, 'Δv = final velocity − initial velocity, as a vector subtraction', NULL, false, NULL, false, NULL, 'Subtracting a vector means adding its negative. Mark scheme (1 mark). B1: C (Δv = final velocity − initial velocity, as a vector subtraction).', 1, NULL, NULL),
('fe504432-d378-5c89-9c91-6ce4cb803429', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 3, 3, 'If v is a vector, what is meant by the vector −v?', NULL, 1, 'multiple_choice'::answer_type, 'A vector of the same size as v pointing in the opposite direction', NULL, false, NULL, false, NULL, 'Subtracting v is the same as adding −v. Mark scheme (1 mark). B1: A (A vector of the same size as v pointing in the opposite direction).', 1, NULL, NULL),
('a18d45fa-c683-5253-8f66-b91904443bc7', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 4, 4, 'A car''s velocity changes from 12 m s⁻¹ east to 20 m s⁻¹ east. Calculate its change in velocity.', NULL, 1, 'numeric'::answer_type, '8', 'm s⁻¹', false, NULL, false, NULL, 'Δv = 20 − 12 = 8.0 m s⁻¹ east. Mark scheme (2 marks). C1: final − initial. A1: Δv = 8.0 m s⁻¹.', 2, NULL, NULL),
('98150609-b32d-5b33-ab9b-9526172a554c', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 5, 5, 'A ball falling at 8.0 m s⁻¹ bounces up at 5.0 m s⁻¹. Taking upwards as positive, calculate its change in velocity.', NULL, 1, 'numeric'::answer_type, '13', 'm s⁻¹', false, NULL, false, NULL, 'Δv = 5.0 − (−8.0) = 13 m s⁻¹ upwards. Mark scheme (2 marks). C1: initial is negative. A1: Δv = 13 m s⁻¹.', 2, NULL, NULL),
('6d96f9e3-3db2-583f-bd70-a7aeb277760e', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 6, 6, 'A car goes round a bend at a steady 15 m s⁻¹. Is its change in velocity zero?', NULL, 1, 'multiple_choice'::answer_type, 'No, because the direction of the velocity changes', NULL, false, NULL, false, NULL, 'Velocity is a vector. Mark scheme (1 mark). B1: D (No, because the direction of the velocity changes).', 1, NULL, NULL),
('7c9c2a49-bd11-55f3-a7e1-d9a8c451bb6c', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 7, 7, 'A car travelling at 25 m s⁻¹ north slows to 10 m s⁻¹ north. Calculate its change in velocity, taking north as positive.', NULL, 1, 'numeric'::answer_type, '-15', 'm s⁻¹', false, NULL, true, NULL, 'Δv = 10 − 25 = −15 m s⁻¹ (15 m s⁻¹ south). Mark scheme (2 marks). C1: final − initial. A1: Δv = −15 m s⁻¹.', 2, NULL, NULL),
('663987b2-cb33-52e7-8a99-663fd4e6d264', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 8, 8, 'A ball rebounds from a wall at the same speed it hit it. What is its change in speed?', NULL, 1, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'Speed is unchanged; velocity is not. Mark scheme (1 mark). B1: B (Zero).', 1, NULL, NULL),
('d2e08625-f175-533d-8495-4c3a67994699', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 9, 9, 'A ball rebounds from a wall at the same speed v it hit it. What is the magnitude of its change in velocity?', NULL, 1, 'multiple_choice'::answer_type, '2v', NULL, false, NULL, false, NULL, 'The velocity reverses: v − (−v) = 2v. Mark scheme (1 mark). B1: C (2v).', 1, NULL, NULL),
('9a5f854e-0a28-5215-9295-7fd7ad404372', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 10, 10, 'A ball moving at 9.0 m s⁻¹ is caught and stopped. Taking its initial direction as positive, calculate its change in velocity.', NULL, 1, 'numeric'::answer_type, '-9', 'm s⁻¹', false, NULL, true, NULL, 'Δv = 0 − 9.0 = −9.0 m s⁻¹. Mark scheme (2 marks). C1: final zero. A1: Δv = −9.0 m s⁻¹.', 2, NULL, NULL),
('e07d68f3-c916-5ca0-acda-be7e01d8dfdf', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 11, 11, 'To find a − b with a scale drawing, which pair of arrows is drawn head to tail?', NULL, 1, 'multiple_choice'::answer_type, 'a and −b', NULL, false, NULL, false, NULL, 'Subtraction is addition of the negative. Mark scheme (1 mark). B1: A (a and −b).', 1, NULL, NULL),
('d2d91267-d56e-5c06-a173-d516b820b193', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 12, 12, 'A cyclist''s velocity changes from 4.0 m s⁻¹ east to 4.0 m s⁻¹ north. Calculate the magnitude of the change in velocity.', NULL, 1, 'numeric'::answer_type, '5.657', 'm s⁻¹', false, NULL, false, NULL, 'Δv = v₂ − v₁ has components 4.0 north and 4.0 west: |Δv| = √(4.0² + 4.0²) = 5.66 m s⁻¹. Mark scheme (2 marks). C1: perpendicular, Pythagoras. A1: Δv = 5.66 m s⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg7c751ac4-t fg7c751ac4-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7c751ac4-t">Change in velocity</title><desc id="fg7c751ac4-d">Initial velocity 4.0 m s⁻¹ east and final velocity 4.0 m s⁻¹ north from a common point; Δv (dashed) runs from the head of v₁ to the head of v₂.</desc><line x1="98.2" y1="201.8" x2="235.5" y2="201.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="241.8,201.8 233.6,205.6 233.6,198" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="255.8" y="205.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 4.0 m s⁻¹</text><line x1="98.2" y1="201.8" x2="98.2" y2="64.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="98.2,58.2 102,66.4 94.4,66.4" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="98.2" y="42.2" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 4.0 m s⁻¹</text><line x1="241.8" y1="201.8" x2="102.7" y2="62.7" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="98.2,58.2 106.7,61.3 101.3,66.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="179.9" y="120.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="98.2" cy="201.8" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Initial velocity 4.0 m s⁻¹ east and final velocity 4.0 m s⁻¹ north from a common point; Δv (dashed) runs from the head of v₁ to the head of v₂.'),
('4fcb8eda-a7cb-599a-9148-3929802aca4f', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 13, 13, 'A cyclist''s velocity changes from 4.0 m s⁻¹ east to 4.0 m s⁻¹ north. In which direction is Δv?', NULL, 1, 'multiple_choice'::answer_type, 'North-west', NULL, false, NULL, false, NULL, 'Δv = v₂ + (−v₁): north plus west. Mark scheme (1 mark). B1: D (North-west).', 1, NULL, NULL),
('fba62c1c-956b-5426-ada1-5db8e8203c1b', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 14, 14, 'Taking west as positive, a train slows from 30 m s⁻¹ to 18 m s⁻¹. Calculate its change in velocity.', NULL, 1, 'numeric'::answer_type, '-12', 'm s⁻¹', false, NULL, true, NULL, 'Δv = 18 − 30 = −12 m s⁻¹, that is 12 m s⁻¹ towards the east. Mark scheme (2 marks). C1: subtraction. A1: Δv = −12 m s⁻¹.', 2, NULL, NULL),
('8524ee94-5770-52df-9e1e-b68cf69d21b3', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 15, 15, 'A ball thrown upward at 12 m s⁻¹ is caught on the way down moving at 12 m s⁻¹. Calculate the magnitude of its change in velocity.', NULL, 1, 'numeric'::answer_type, '24', 'm s⁻¹', false, NULL, false, NULL, 'Taking up as positive: Δv = −12 − 12 = −24 m s⁻¹, so the magnitude is 12 + 12 = 24 m s⁻¹. Mark scheme (1 mark). A1: Δv = 24 m s⁻¹.', 1, NULL, NULL),
('d44e848c-3a68-5bbc-ba08-fccdf557a2f7', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 16, 16, 'Which quantity is found by subtracting two velocity vectors?', NULL, 1, 'multiple_choice'::answer_type, 'The change in velocity (or a relative velocity)', NULL, false, NULL, false, NULL, 'For example Δv = v₂ − v₁, or v_A − v_B for a relative velocity. Mark scheme (1 mark). B1: B (The change in velocity (or a relative velocity)).', 1, NULL, NULL),
('ed40396d-0bea-5c48-92fa-9d920a681f2b', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 17, 17, 'Car A moves east at 30 m s⁻¹ and car B moves east at 22 m s⁻¹. Calculate the velocity of A relative to B.', NULL, 1, 'numeric'::answer_type, '8', 'm s⁻¹', false, NULL, false, NULL, 'v_AB = v_A − v_B = 30 − 22 = 8.0 m s⁻¹ east. Mark scheme (2 marks). C1: v_A − v_B. A1: v_AB = 8.0 m s⁻¹.', 2, NULL, NULL),
('d873ea51-4700-583f-b197-72a83f21b64f', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 18, 18, 'A bus speeds up from 8.0 m s⁻¹ to 14 m s⁻¹ along a straight road. Calculate its change in velocity.', NULL, 1, 'numeric'::answer_type, '6', 'm s⁻¹', false, NULL, false, NULL, 'Δv = 14 − 8.0 = 6.0 m s⁻¹ forwards. Mark scheme (2 marks). C1: final − initial. A1: Δv = 6.0 m s⁻¹.', 2, NULL, NULL),
('07290953-d0e8-5158-a993-b5729c6557cd', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 19, 19, 'A ball falls vertically and bounces straight back up more slowly. In which direction is its change in velocity?', NULL, 1, 'multiple_choice'::answer_type, 'Upwards', NULL, false, NULL, false, NULL, 'Δv = v_up − v_down points upwards. Mark scheme (1 mark). B1: B (Upwards).', 1, NULL, NULL),
('9b7cd0fb-35dd-5935-b2b2-2c79293ad89f', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 20, 20, 'A trolley moving at 0.80 m s⁻¹ hits a buffer and rebounds at 0.60 m s⁻¹. Taking the initial direction as positive, calculate its change in velocity.', NULL, 1, 'numeric'::answer_type, '-1.4', 'm s⁻¹', false, NULL, true, NULL, 'Δv = −0.60 − 0.80 = −1.4 m s⁻¹. Mark scheme (2 marks). C1: signs. A1: Δv = −1.4 m s⁻¹.', 2, NULL, NULL),
('42609279-dacb-53d1-8ae3-dc959ece6fd8', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 21, 21, 'A car rounds a 90° bend, its velocity changing from 15 m s⁻¹ north to 15 m s⁻¹ east in 6.0 s. Calculate the magnitude of the average acceleration.', NULL, 2, 'numeric'::answer_type, '3.536', 'm s⁻²', false, NULL, false, NULL, '|Δv| = √(15² + 15²) = 21.21 m s⁻¹; a = 21.21 ÷ 6.0 = 3.54 m s⁻². Mark scheme (3 marks). C1: |Δv|. C1: ÷ time. A1: a = 3.54 m s⁻².', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg0d3e5416-t fg0d3e5416-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg0d3e5416-t">Turning a 90° bend</title><desc id="fg0d3e5416-d">Initial velocity 15 m s⁻¹ north and final velocity 15 m s⁻¹ east from a common point, with Δv dashed.</desc><line x1="94.6" y1="205.4" x2="94.6" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="94.6,54.6 98.4,62.8 90.8,62.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="94.6" y="38.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 15 m s⁻¹</text><line x1="94.6" y1="205.4" x2="239.1" y2="205.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="245.4,205.4 237.2,209.2 237.2,201.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="259.4" y="209.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 15 m s⁻¹</text><line x1="94.6" y1="54.6" x2="240.9" y2="200.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="245.4,205.4 236.9,202.3 242.3,196.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="179.9" y="120.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="94.6" cy="205.4" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Initial velocity 15 m s⁻¹ north and final velocity 15 m s⁻¹ east from a common point, with Δv dashed.'),
('667a4177-e7e4-58bd-b060-6dbe115bc6a3', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 22, 22, 'A tennis ball arrives at 20 m s⁻¹ and is returned along the same line at 30 m s⁻¹. The contact time is 5.0 ms. Calculate the magnitude of its average acceleration.', NULL, 2, 'numeric'::answer_type, '10000', 'm s⁻²', false, NULL, false, NULL, '|Δv| = 30 − (−20) = 50 m s⁻¹; a = 50 ÷ 5.0 × 10⁻³ = 10 000 m s⁻². Mark scheme (3 marks). C1: |Δv| = 50. C1: ÷ time in s. A1: a = 1.0 × 10⁴ m s⁻².', 3, NULL, NULL),
('b37d9be4-500c-5444-bad3-3026b6a1640d', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 23, 23, 'An ice-hockey puck is moving east at 6.0 m s⁻¹ when it is struck; afterwards it moves north at 8.0 m s⁻¹. Find the magnitude of the change in its velocity.', NULL, 2, 'numeric'::answer_type, '10', 'm s⁻¹', false, NULL, false, NULL, '|Δv| = √(6.0² + 8.0²) = 10 m s⁻¹. Mark scheme (3 marks). C1: −v₁ is 6.0 west. C1: Pythagoras. A1: Δv = 10 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg06a66758-t fg06a66758-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg06a66758-t">Puck struck</title><desc id="fg06a66758-d">Initial velocity 6.0 m s⁻¹ east and final velocity 8.0 m s⁻¹ north from a common point, with Δv dashed.</desc><line x1="110" y1="210" x2="223.7" y2="210" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,210 221.8,213.8 221.8,206.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="244" y="214" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 6.0 m s⁻¹</text><line x1="110" y1="210" x2="110" y2="56.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,50 113.8,58.2 106.2,58.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="110" y="34" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 8.0 m s⁻¹</text><line x1="230" y1="210" x2="113.8" y2="55" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="110,50 117.9,54.2 111.9,58.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="181.2" y="121.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="110" cy="210" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Initial velocity 6.0 m s⁻¹ east and final velocity 8.0 m s⁻¹ north from a common point, with Δv dashed.'),
('aa4b30b4-3640-52ea-b9de-120b1c9b5458', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 24, 24, 'A puck''s velocity changes from 6.0 m s⁻¹ east to 8.0 m s⁻¹ north. Calculate the angle of Δv measured west of north.', NULL, 2, 'numeric'::answer_type, '36.87', '°', false, NULL, false, NULL, 'Δv has components 8.0 north and 6.0 west: θ = tan⁻¹(6.0 ÷ 8.0) = 36.9°. Mark scheme (3 marks). C1: components. C1: angle. A1: θ = 36.9°.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg38ee8de7-t fg38ee8de7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg38ee8de7-t">Direction of Δv</title><desc id="fg38ee8de7-d">Initial velocity 6.0 m s⁻¹ east and final velocity 8.0 m s⁻¹ north from a common point; Δv (dashed) points north-west.</desc><line x1="110" y1="210" x2="223.7" y2="210" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,210 221.8,213.8 221.8,206.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="244" y="214" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 6.0 m s⁻¹</text><line x1="110" y1="210" x2="110" y2="56.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,50 113.8,58.2 106.2,58.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="110" y="34" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 8.0 m s⁻¹</text><line x1="230" y1="210" x2="113.8" y2="55" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="110,50 117.9,54.2 111.9,58.8" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="181.2" y="121.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="110" cy="210" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Initial velocity 6.0 m s⁻¹ east and final velocity 8.0 m s⁻¹ north from a common point; Δv (dashed) points north-west.'),
('fc2fa3e4-d203-5a32-9d51-bceb31bff22d', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 25, 25, 'Car A travels north at 20 m s⁻¹ and car B east at 20 m s⁻¹. What is the velocity of A relative to B?', NULL, 2, 'multiple_choice'::answer_type, '28 m s⁻¹ towards the north-west', NULL, false, NULL, false, NULL, 'v_A − v_B = north 20 + west 20. Mark scheme (3 marks). C1: v_A − v_B. C1: magnitude and direction. A1: C (28 m s⁻¹ towards the north-west).', 3, NULL, NULL),
('74647067-5670-54cf-b750-beffe5f4447f', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 26, 26, 'A ball hits a floor at 7.0 m s⁻¹ at 90° and rebounds at 5.0 m s⁻¹. The contact time is 0.020 s. Calculate the average acceleration during contact.', NULL, 2, 'numeric'::answer_type, '600', 'm s⁻²', false, NULL, false, NULL, '|Δv| = 5.0 + 7.0 = 12 m s⁻¹; a = 12 ÷ 0.020 = 600 m s⁻². Mark scheme (3 marks). C1: |Δv|. C1: ÷ t. A1: a = 600 m s⁻².', 3, NULL, NULL),
('389a3df4-1d8c-54a4-ae8d-2d3e26d465b7', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 27, 27, 'A ball strikes a wall at 10 m s⁻¹ at 60° to the wall and rebounds at the same speed and angle. Calculate the magnitude of the change in velocity.', NULL, 2, 'numeric'::answer_type, '17.32', 'm s⁻¹', false, NULL, false, NULL, 'Only the component perpendicular to the wall reverses: |Δv| = 2 × 10 × sin 60° = 17.3 m s⁻¹. Mark scheme (4 marks). M1: parallel component unchanged. C1: perpendicular component. C1: doubled. A1: Δv = 17.3 m s⁻¹.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg492770c3-t fg492770c3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg492770c3-t">Glancing rebound</title><desc id="fg492770c3-d">Velocities of 10 m s⁻¹ before and after a rebound, each at 60° to the wall, drawn from a common point; Δv (dashed) is perpendicular to the wall.</desc><line x1="146.9" y1="130" x2="189.9" y2="204.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="193.1,210 185.7,204.8 192.3,201" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="200.1" y="226.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 10 m s⁻¹</text><line x1="146.9" y1="130" x2="189.9" y2="55.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="193.1,50 192.3,59 185.7,55.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="200.1" y="41.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 10 m s⁻¹</text><line x1="193.1" y1="210" x2="193.1" y2="56.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="193.1,50 196.9,58.2 189.3,58.2" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="207.1" y="130" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="146.9" cy="130" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Velocities of 10 m s⁻¹ before and after a rebound, each at 60° to the wall, drawn from a common point; Δv (dashed) is perpendicular to the wall.'),
('86bc5d19-33c5-50dd-9a63-c0de33071dec', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 28, 28, 'A runner''s velocity changes from 5.0 m s⁻¹ north to 3.0 m s⁻¹ south. Calculate the change in velocity, taking north as positive.', NULL, 2, 'numeric'::answer_type, '-8', 'm s⁻¹', false, NULL, true, NULL, 'Δv = −3.0 − 5.0 = −8.0 m s⁻¹ (8.0 m s⁻¹ south). Mark scheme (3 marks). C1: signs. C1: value. A1: Δv = −8.0 m s⁻¹.', 3, NULL, NULL),
('a06f0dd7-9819-5c0d-ad11-f47c513df54f', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 29, 29, 'Why can the change in velocity of an object moving at constant speed be non-zero?', NULL, 2, 'multiple_choice'::answer_type, 'Because velocity is a vector and its direction can change', NULL, false, NULL, false, NULL, 'Δv depends on direction too. Mark scheme (3 marks). C1: vector. C1: direction change. A1: A (Because velocity is a vector and its direction can change).', 3, NULL, NULL),
('fa5a318f-ed79-5a65-9f05-4a5f06b4f6ca', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 30, 30, 'Train P moves north at 25 m s⁻¹ and train Q moves south at 15 m s⁻¹. Calculate the speed of P relative to Q.', NULL, 2, 'numeric'::answer_type, '40', 'm s⁻¹', false, NULL, false, NULL, 'v_PQ = 25 − (−15) = 40 m s⁻¹ north. Mark scheme (3 marks). C1: opposite signs. C1: value. A1: v_PQ = 40 m s⁻¹.', 3, NULL, NULL),
('9a0c3b80-14e0-522d-a18f-5af21ac7d9ed', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 31, 31, 'A satellite moving at 7.5 km s⁻¹ goes a quarter of the way round a circular orbit. Calculate the magnitude of its change in velocity, in km s⁻¹.', NULL, 2, 'numeric'::answer_type, '10.61', 'km s⁻¹', false, NULL, false, NULL, 'The velocity turns through 90°: |Δv| = √(7.5² + 7.5²) = 10.6 km s⁻¹. Mark scheme (3 marks). C1: 90° turn. C1: Pythagoras. A1: Δv = 10.6 km s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fgdf788ce0-t fgdf788ce0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgdf788ce0-t">Quarter orbit</title><desc id="fgdf788ce0-d">Velocities of 7.5 km s⁻¹ at the start and after a quarter orbit, 90° apart, from a common point; Δv is dashed.</desc><line x1="104.9" y1="195.1" x2="228.8" y2="195.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="235.1,195.1 226.9,198.9 226.9,191.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="249.1" y="199.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 7.5 km s⁻¹</text><line x1="104.9" y1="195.1" x2="104.9" y2="71.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="104.9,64.9 108.7,73.1 101.1,73.1" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="104.9" y="48.9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 7.5 km s⁻¹</text><line x1="235.1" y1="195.1" x2="109.4" y2="69.4" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="104.9,64.9 113.4,68 108,73.4" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="179.9" y="120.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="104.9" cy="195.1" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'Velocities of 7.5 km s⁻¹ at the start and after a quarter orbit, 90° apart, from a common point; Δv is dashed.'),
('c38fda60-52bf-5e19-839e-7cae61b33463', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 32, 32, 'After half an orbit, a satellite circling at 7.5 km s⁻¹ is moving in the opposite direction. What is the magnitude of its velocity change, in km s⁻¹?', NULL, 2, 'numeric'::answer_type, '15', 'km s⁻¹', false, NULL, false, NULL, 'The velocity reverses: |Δv| = 7.5 + 7.5 = 15 km s⁻¹. Mark scheme (3 marks). C1: reversal. C1: value. A1: Δv = 15 km s⁻¹.', 3, NULL, NULL),
('9d14be18-c4af-5e60-8f0f-cf5c5fe8c90f', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 33, 33, 'Velocity v₁ = 10 m s⁻¹ east and v₂ = 10 m s⁻¹ at 60° north of east. Calculate |v₂ − v₁|.', NULL, 2, 'numeric'::answer_type, '10', 'm s⁻¹', false, NULL, false, NULL, 'The triangle is equilateral (60° between equal sides): |Δv| = √(10² + 10² − 2 × 10 × 10 × cos 60°) = 10 m s⁻¹. Mark scheme (3 marks). C1: cosine rule. C1: value. A1: Δv = 10 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fgec225fb7-t fgec225fb7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgec225fb7-t">Equilateral triangle</title><desc id="fgec225fb7-d">Velocities of 10 m s⁻¹ east and 10 m s⁻¹ at 60° north of east from a common point; Δv is dashed.</desc><line x1="94.6" y1="195.3" x2="239.1" y2="195.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="245.4,195.3 237.2,199.1 237.2,191.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="259.4" y="199.3" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 10 m s⁻¹</text><line x1="94.6" y1="195.3" x2="166.8" y2="70.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,64.7 169.2,73.7 162.6,69.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="177" y="56.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 10 m s⁻¹</text><line x1="245.4" y1="195.3" x2="173.2" y2="70.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="170,64.7 177.4,69.9 170.8,73.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="219.8" y="123" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="94.6" cy="195.3" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Velocities of 10 m s⁻¹ east and 10 m s⁻¹ at 60° north of east from a common point; Δv is dashed.'),
('d2e2ca0d-6052-5bdf-86d7-3bf969f72a8a', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 34, 34, 'Two cyclists ride side by side north at 6 m s⁻¹. What is the velocity of one relative to the other?', NULL, 2, 'multiple_choice'::answer_type, 'Zero', NULL, false, NULL, false, NULL, 'Equal velocities: v₁ − v₂ = 6 − 6 = 0. Mark scheme (3 marks). C1: equal velocities. C1: relative velocity zero. A1: D (Zero).', 3, NULL, NULL),
('326243d0-2208-54cf-a41f-92ff97b8f7e2', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 35, 35, 'A boat moves at 5.0 m s⁻¹ east and a seagull flies at 12 m s⁻¹ north. Calculate the speed of the gull relative to the boat.', NULL, 2, 'numeric'::answer_type, '13', 'm s⁻¹', false, NULL, false, NULL, 'v = √(12² + 5.0²) = 13 m s⁻¹. Mark scheme (3 marks). C1: v_gull − v_boat. C1: Pythagoras. A1: v = 13 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg58d4ff7a-t fg58d4ff7a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg58d4ff7a-t">Gull relative to boat</title><desc id="fg58d4ff7a-d">v(boat) = 5.0 m s⁻¹ east and v(gull) = 12 m s⁻¹ north from a common point; v(gull) − v(boat) is dashed.</desc><line x1="136.7" y1="210" x2="197" y2="210" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="203.3,210 195.2,213.8 195.2,206.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="217.3" y="214" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">boat: 5.0 m s⁻¹</text><line x1="136.7" y1="210" x2="136.7" y2="56.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="136.7,50 140.5,58.2 132.9,58.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="136.7" y="34" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">gull: 12 m s⁻¹</text><line x1="203.3" y1="210" x2="139.1" y2="55.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="136.7,50 143.3,56.1 136.3,59" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="182.9" y="124.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v(gull) − v(boat)</text><circle cx="136.7" cy="210" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'v(boat) = 5.0 m s⁻¹ east and v(gull) = 12 m s⁻¹ north from a common point; v(gull) − v(boat) is dashed.'),
('5fe9ba91-7cdb-5703-bb5c-348fb402e13d', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 36, 36, 'A hockey ball travelling at 14 m s⁻¹ east is struck so that it leaves at 14 m s⁻¹ north. The stick is in contact for 0.050 s. Calculate the average acceleration.', NULL, 2, 'numeric'::answer_type, '396', 'm s⁻²', false, NULL, false, NULL, '|Δv| = √(14² + 14²) = 19.80 m s⁻¹; a = 19.80 ÷ 0.050 = 396 m s⁻². Mark scheme (4 marks). M1: Δv perpendicular. C1: value. C1: a. A1: a = 396 m s⁻².', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg10844c79-t fg10844c79-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg10844c79-t">Hockey ball</title><desc id="fg10844c79-d">Initial velocity 14 m s⁻¹ east and final velocity 14 m s⁻¹ north from a common point; Δv is dashed.</desc><line x1="94.6" y1="205.4" x2="239.1" y2="205.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="245.4,205.4 237.2,209.2 237.2,201.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="259.4" y="209.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 14 m s⁻¹</text><line x1="94.6" y1="205.4" x2="94.6" y2="60.9" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="94.6,54.6 98.4,62.8 90.8,62.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="94.6" y="38.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 14 m s⁻¹</text><line x1="245.4" y1="205.4" x2="99.1" y2="59.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="94.6,54.6 103.1,57.7 97.7,63.1" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="179.9" y="120.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="94.6" cy="205.4" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Initial velocity 14 m s⁻¹ east and final velocity 14 m s⁻¹ north from a common point; Δv is dashed.'),
('54a6dbb6-1ad1-58ee-9d5b-6d5fcee2ecc6', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 37, 37, 'A lift moving down at 3.0 m s⁻¹ comes to rest and then moves up at 2.0 m s⁻¹. Taking up as positive, calculate its total change in velocity.', NULL, 2, 'numeric'::answer_type, '5', 'm s⁻¹', false, NULL, false, NULL, 'Δv = 2.0 − (−3.0) = 5.0 m s⁻¹ upwards. Mark scheme (3 marks). C1: signs. C1: value. A1: Δv = 5.0 m s⁻¹.', 3, NULL, NULL),
('32bb906a-dc79-5d17-94e6-61f6a66975eb', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 38, 38, 'A model boat heading north at 3.0 m s⁻¹ is turned so that it heads east at 4.0 m s⁻¹. By how much has its velocity changed (magnitude)?', NULL, 2, 'numeric'::answer_type, '5', 'm s⁻¹', false, NULL, false, NULL, '|Δv| = √(3.0² + 4.0²) = 5.0 m s⁻¹. Mark scheme (3 marks). C1: perpendicular. C1: Pythagoras. A1: Δv = 5.0 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg9ca2b578-t fg9ca2b578-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9ca2b578-t">Model boat turning</title><desc id="fg9ca2b578-d">Initial velocity 3.0 m s⁻¹ north and final velocity 4.0 m s⁻¹ east from a common point; Δv is dashed.</desc><line x1="98.2" y1="183.9" x2="98.2" y2="82.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="98.2,76.2 102,84.3 94.4,84.3" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="98.2" y="60.2" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 3.0 m s⁻¹</text><line x1="98.2" y1="183.9" x2="235.5" y2="183.9" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="241.8,183.9 233.6,187.7 233.6,180" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="255.8" y="187.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 4.0 m s⁻¹</text><line x1="98.2" y1="76.2" x2="236.8" y2="180.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="241.8,183.9 233,182 237.6,175.9" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="178.4" y="118.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="98.2" cy="183.9" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Initial velocity 3.0 m s⁻¹ north and final velocity 4.0 m s⁻¹ east from a common point; Δv is dashed.'),
('a10882f9-ea64-54f7-919b-23d46f8217cd', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 39, 39, 'A football moving west at 18 m s⁻¹ is kicked back east at 22 m s⁻¹. The kick lasts 0.10 s. Calculate the magnitude of the average acceleration.', NULL, 2, 'numeric'::answer_type, '400', 'm s⁻²', false, NULL, false, NULL, '|Δv| = 22 + 18 = 40 m s⁻¹; a = 40 ÷ 0.10 = 400 m s⁻². Mark scheme (3 marks). C1: |Δv|. C1: ÷ t. A1: a = 400 m s⁻².', 3, NULL, NULL),
('28884a37-7028-58f7-af1d-9180240b53ad', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 40, 40, 'Why is |Δv| for a ball that rebounds from a wall larger than its change in speed?', NULL, 2, 'multiple_choice'::answer_type, 'The direction reverses, so the two speeds add in Δv', NULL, false, NULL, false, NULL, 'For a rebound |Δv| = v₁ + v₂. Mark scheme (3 marks). C1: reversal. C1: magnitudes add. A1: C (The direction reverses, so the two speeds add in Δv).', 3, NULL, NULL),
('d7ec5579-ea4d-5a5f-8f9a-1d10a076c41d', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 41, 41, 'A pendulum bob passes the lowest point at 1.2 m s⁻¹ to the left, and half a period later at 1.2 m s⁻¹ to the right. Calculate the magnitude of its change in velocity.', NULL, 2, 'numeric'::answer_type, '2.4', 'm s⁻¹', false, NULL, false, NULL, '|Δv| = 1.2 + 1.2 = 2.4 m s⁻¹. Mark scheme (3 marks). C1: reversal. C1: value. A1: Δv = 2.4 m s⁻¹.', 3, NULL, NULL),
('fb4070e3-b76c-5b53-818b-fc2b901f282f', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 42, 42, 'A car''s velocity changes from 20 m s⁻¹ north to 20 m s⁻¹ west in 8.0 s. (a) Draw the vector diagram for Δv. (b) Calculate |Δv|. (c) Calculate the average acceleration.', NULL, 3, 'numeric'::answer_type, '3.536', 'm s⁻²', false, NULL, false, NULL, '(a) Δv = v₂ + (−v₁): 20 west plus 20 south. (b) |Δv| = √(20² + 20²) = 28.28 m s⁻¹. (c) a = 28.28 ÷ 8.0 = 3.54 m s⁻² towards the south-west. Mark scheme (5 marks). B1: diagram. C1: |Δv|. M1: a = Δv/t. C1: value. A1: a = 3.54 m s⁻².', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg050cccf4-t fg050cccf4-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg050cccf4-t">North to west</title><desc id="fg050cccf4-d">Initial velocity 20 m s⁻¹ north and final velocity 20 m s⁻¹ west from a common point; Δv is dashed.</desc><line x1="245.4" y1="205.4" x2="245.4" y2="60.9" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="245.4,54.6 249.2,62.8 241.6,62.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="245.4" y="38.6" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 20 m s⁻¹</text><line x1="245.4" y1="205.4" x2="100.9" y2="205.4" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="94.6,205.4 102.8,201.6 102.8,209.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="80.6" y="209.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 20 m s⁻¹</text><line x1="245.4" y1="54.6" x2="99.1" y2="200.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="94.6,205.4 97.7,196.9 103.1,202.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="160.1" y="120.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="245.4" cy="205.4" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Initial velocity 20 m s⁻¹ north and final velocity 20 m s⁻¹ west from a common point; Δv is dashed.'),
('6800fd67-59e0-5e30-b0fd-1d29944be71b', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 43, 43, 'A ship at 6.0 m s⁻¹ due north changes course to 6.0 m s⁻¹ on a bearing of 060° in 40 s. (a) Find the components of each velocity. (b) Calculate |Δv|. (c) Calculate the average acceleration.', NULL, 3, 'numeric'::answer_type, '0.15', 'm s⁻²', false, NULL, false, NULL, '(a) v₁ = (0, 6.0); v₂ = (6.0 sin 60°, 6.0 cos 60°) = (5.196, 3.0). (b) |Δv| = √(5.196² + (3.0 − 6.0)²) = 6.0 m s⁻¹. (c) a = 6.0 ÷ 40 = 0.150 m s⁻². Mark scheme (6 marks). C1: v₁. C1: v₂ components. M1: subtract components. C1: |Δv|. C1: value. A1: a = 0.15 m s⁻².', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fgbdd86f81-t fgbdd86f81-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbdd86f81-t">Change of course</title><desc id="fgbdd86f81-d">Velocities of 6.0 m s⁻¹ north and 6.0 m s⁻¹ on a bearing of 060° from a common point; Δv is dashed.</desc><line x1="100.7" y1="210" x2="100.7" y2="56.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="100.7,50 104.5,58.2 96.9,58.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="100.7" y="34" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">v₁ = 6.0 m s⁻¹</text><line x1="100.7" y1="210" x2="233.8" y2="133.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="239.3,130 234.1,137.4 230.3,130.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="251.4" y="127" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">v₂ = 6.0 m s⁻¹</text><line x1="100.7" y1="50" x2="233.8" y2="126.8" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="239.3,130 230.3,129.2 234.1,122.6" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="177" y="77.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">Δv</text><circle cx="100.7" cy="210" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'Velocities of 6.0 m s⁻¹ north and 6.0 m s⁻¹ on a bearing of 060° from a common point; Δv is dashed.'),
('9f242475-9178-5319-a762-507172a428ab', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 44, 44, 'A ball hits a wall at 12 m s⁻¹ at 30° to the normal and rebounds at 9.0 m s⁻¹ at 30° to the normal on the other side. (a) Find the change in the normal component. (b) Find the change in the parallel component. (c) Calculate |Δv|.', NULL, 3, 'numeric'::answer_type, '18.25', 'm s⁻¹', false, NULL, false, NULL, '(a) Normal: 9.0 cos 30° + 12 cos 30° = 18.19 m s⁻¹. (b) Parallel: 9.0 sin 30° − 12 sin 30° = −1.5 m s⁻¹. (c) |Δv| = √(18.19² + 1.5²) = 18.2 m s⁻¹. Mark scheme (5 marks). C1: normal change. C1: parallel change. M1: Pythagoras. C1: value. A1: Δv = 18.2 m s⁻¹.', 5, NULL, NULL),
('a68d65c8-25f7-543d-bd8d-dec8c6b0e29c', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 45, 45, 'Ship A sails east at 8.0 m s⁻¹; ship B sails north at 6.0 m s⁻¹. (a) Calculate the velocity of B relative to A (magnitude). (b) Calculate its direction west of north. (c) Calculate how much the separation changes in 10 minutes if they start at the same point.', NULL, 3, 'numeric'::answer_type, '6 km', 'km', false, NULL, false, NULL, '(a) v_BA = v_B − v_A: 6.0 north and 8.0 west; |v| = √(6.0² + 8.0²) = 10 m s⁻¹. (b) θ = tan⁻¹(8.0 ÷ 6.0) = 53.1° west of north. (c) d = 10 × 600 = 6000 m. In km: 6000 ÷ 1000 = 6.0. Mark scheme (6 marks). M1: v_B − v_A. C1: magnitude. C1: direction. M1: d = vt. C1: value. A1: d = 6.0 km.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg5068ddbd-t fg5068ddbd-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5068ddbd-t">Relative velocity of two ships</title><desc id="fg5068ddbd-d">v(A) = 8.0 m s⁻¹ east and v(B) = 6.0 m s⁻¹ north from a common point; v(B) − v(A) is dashed from the head of v(A) to the head of v(B).</desc><line x1="87.9" y1="191.6" x2="245.8" y2="191.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="252.1,191.6 244,195.4 244,187.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="266.1" y="195.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">A: 8.0 m s⁻¹</text><line x1="87.9" y1="191.6" x2="87.9" y2="74.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="87.9,68.4 91.7,76.6 84.1,76.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="87.9" y="52.4" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">B: 6.0 m s⁻¹</text><line x1="252.1" y1="191.6" x2="92.9" y2="72.2" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="87.9,68.4 96.7,70.3 92.1,76.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="178.4" y="118.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v(B) − v(A)</text><circle cx="87.9" cy="191.6" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'v(A) = 8.0 m s⁻¹ east and v(B) = 6.0 m s⁻¹ north from a common point; v(B) − v(A) is dashed from the head of v(A) to the head of v(B).'),
('dfff4594-2283-514c-a3a2-eb60d950d218', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 46, 46, 'A car travels round a circular track at 18 m s⁻¹. (a) Calculate |Δv| after one-sixth of a lap. (b) Explain why |Δv| is greatest after half a lap.', NULL, 3, 'numeric'::answer_type, '18', 'm s⁻¹', false, NULL, false, NULL, '(a) The velocity turns through 60°, forming an equilateral triangle: |Δv| = √(18² + 18² − 2 × 18 × 18 × cos 60°) = 18 m s⁻¹. (b) After half a lap the velocity has reversed, so |Δv| = 36 m s⁻¹, the largest possible. Mark scheme (5 marks). M1: angle turned 60°. C1: cosine rule. C1: value. B1: reversal gives 2v. A1: Δv = 18 m s⁻¹.', 5, NULL, NULL),
('4b0adb12-bd97-50de-b0ca-519e554efc94', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 47, 47, 'A bat changes a ball''s velocity from 25 m s⁻¹ horizontally towards the batter to 35 m s⁻¹ at 30° above the horizontal away from the batter. (a) Find the horizontal and vertical components of Δv. (b) Calculate |Δv|.', NULL, 3, 'numeric'::answer_type, '58.01', 'm s⁻¹', false, NULL, false, NULL, '(a) Horizontal: 35 cos 30° + 25 = 55.31 m s⁻¹; vertical: 35 sin 30° = 17.5 m s⁻¹. (b) |Δv| = √(55.31² + 17.5²) = 58.0 m s⁻¹. Mark scheme (5 marks). C1: horizontal. C1: vertical. M1: Pythagoras. C1: value. A1: Δv = 58.0 m s⁻¹.', 5, NULL, NULL),
('de82ec37-e7e4-54ab-915f-036d89f6a2af', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 48, 48, 'Rain falls vertically at 5.0 m s⁻¹. A runner moves east at 3.0 m s⁻¹. (a) Write the velocity of the rain relative to the runner as a vector subtraction. (b) Calculate its magnitude. (c) Calculate the angle to the vertical at which she should tilt her umbrella.', NULL, 3, 'numeric'::answer_type, '30.96', '°', false, NULL, false, NULL, '(a) v_rel = v_rain − v_runner. (b) |v| = √(5.0² + 3.0²) = 5.83 m s⁻¹. (c) θ = tan⁻¹(3.0 ÷ 5.0) = 31.0°, tilted forwards. Mark scheme (6 marks). B1: subtraction. C1: components. C1: magnitude. M1: tan θ. C1: value. A1: θ = 31.0°.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg6061825b-t fg6061825b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg6061825b-t">Rain relative to a runner</title><desc id="fg6061825b-d">v(runner) = 3.0 m s⁻¹ east and v(rain) = 5.0 m s⁻¹ down from a common point; v(rain) − v(runner) is dashed.</desc><line x1="122" y1="50" x2="211.7" y2="50" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="218,50 209.8,53.8 209.8,46.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="232" y="54" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">runner: 3.0 m s⁻¹</text><line x1="122" y1="50" x2="122" y2="203.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="122,210 118.2,201.8 125.8,201.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="122" y="236" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">rain: 5.0 m s⁻¹</text><line x1="218" y1="50" x2="125.2" y2="204.6" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="122,210 122.9,201 129.5,205" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="182" y="137.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v(rain) − v(runner)</text><circle cx="122" cy="50" r="3.4" style="fill:currentColor;stroke:none"/></svg>', 'v(runner) = 3.0 m s⁻¹ east and v(rain) = 5.0 m s⁻¹ down from a common point; v(rain) − v(runner) is dashed.'),
('c44af100-880c-55dc-80a8-2055dd7b3950', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 49, 49, 'An object moves in a circle of radius 0.50 m at 2.0 m s⁻¹. (a) Calculate the time for a quarter turn. (b) Calculate |Δv| for a quarter turn. (c) Calculate the average acceleration over the quarter turn.', NULL, 3, 'numeric'::answer_type, '7.203', 'm s⁻²', false, NULL, false, NULL, '(a) t = (2π × 0.50 ÷ 4) ÷ 2.0 = 0.3927 s. (b) |Δv| = √(2.0² + 2.0²) = 2.828 m s⁻¹. (c) a = 2.828 ÷ 0.3927 = 7.20 m s⁻². Mark scheme (5 marks). C1: time. C1: |Δv|. M1: a = Δv/t. C1: value. A1: a = 7.20 m s⁻².', 5, NULL, NULL),
('ecc13948-0229-5c5b-9bba-35e1f8acb55f', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 50, 50, 'A ball is thrown at 20 m s⁻¹ at 40° above the horizontal and later moves at 16.3 m s⁻¹ at 20° below the horizontal. (a) Show that the horizontal component is unchanged (to 2 s.f.). (b) Calculate the change in vertical velocity, taking up as positive.', NULL, 3, 'numeric'::answer_type, '-18.43', 'm s⁻¹', false, NULL, true, NULL, '(a) 20 cos 40° = 15.3 and 16.3 cos 20° = 15.3 m s⁻¹. (b) Δv_y = −16.3 sin 20° − 20 sin 40° = −18.4 m s⁻¹. Mark scheme (5 marks). C1: horizontal components. B1: equal. M1: final − initial vertical. C1: value. A1: Δv_y = −18.4 m s⁻¹.', 5, NULL, NULL),
('f764e17d-db53-57a0-9ceb-330c39509f43', '4653a171-76f9-4b44-bc1d-19802787195f', '19109221-dd23-4986-8f92-84b0ea2c6033', 'a-level', '1.7', '9702 coursebook 1.7 · Subtracting vectors', 51, 51, 'Car A travels north at 15 m s⁻¹ and car B travels east at 20 m s⁻¹. (a) Write the velocity of B relative to A as a vector subtraction. (b) Calculate its magnitude. (c) Calculate its angle east of south.', NULL, 3, 'numeric'::answer_type, '53.13', '°', false, NULL, false, NULL, '(a) v_BA = v_B − v_A: 20 east and 15 south. (b) √(20² + 15²) = 25 m s⁻¹. (c) θ = tan⁻¹(20 ÷ 15) = 53.1°. Mark scheme (5 marks). B1: subtraction. C1: magnitude. M1: tan θ. C1: value. A1: θ = 53.1°.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fg2f57e571-t fg2f57e571-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg2f57e571-t">Relative velocity of two cars</title><desc id="fg2f57e571-d">v(A) = 15 m s⁻¹ north and v(B) = 20 m s⁻¹ east from a common point; v(B) − v(A) is dashed.</desc><line x1="84.3" y1="194.3" x2="84.3" y2="72" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="84.3,65.7 88.1,73.9 80.5,73.9" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="84.3" y="49.7" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">A: 15 m s⁻¹</text><line x1="84.3" y1="194.3" x2="249.4" y2="194.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="255.7,194.3 247.6,198.1 247.6,190.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="269.7" y="198.3" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">B: 20 m s⁻¹</text><line x1="84.3" y1="65.7" x2="250.7" y2="190.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/><polygon points="255.7,194.3 246.9,192.4 251.5,186.4" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="178.4" y="118.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">v(B) − v(A)</text><circle cx="84.3" cy="194.3" r="3.4" style="fill:currentColor;stroke:none"/><line x1="318" y1="50" x2="318" y2="22.9" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="318,18 321,24.3 315,24.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="318" y="9" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">N</text></svg>', 'v(A) = 15 m s⁻¹ north and v(B) = 20 m s⁻¹ east from a common point; v(B) − v(A) is dashed.')
