INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('aecfa371-6c5c-502b-9575-9a4766fa44ad', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 1, 1, 'Which list contains only vector quantities?', NULL, 1, 'multiple_choice'::answer_type, 'Force, momentum, acceleration', NULL, false, NULL, false, NULL, 'Each of these needs a direction. Mark scheme (1 mark). B1: C (Force, momentum, acceleration).', 1, NULL, NULL),
('27d0e636-8961-5e54-9851-a3d1f90f7841', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 2, 2, 'Choose the list in which every quantity is a scalar.', NULL, 1, 'multiple_choice'::answer_type, 'Mass, energy, temperature', NULL, false, NULL, false, NULL, 'None of these has a direction. Mark scheme (1 mark). B1: A (Mass, energy, temperature).', 1, NULL, NULL),
('b79b591f-9a8d-56e7-8453-109c4f582175', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 3, 3, 'Is weight a scalar or a vector?', NULL, 1, 'multiple_choice'::answer_type, 'A vector, acting vertically downwards', NULL, false, NULL, false, NULL, 'Weight is the gravitational force on a mass, so it has a direction. Mark scheme (1 mark). B1: D (A vector, acting vertically downwards).', 1, NULL, NULL),
('bd3d1acd-230d-5b3d-bf2d-93a233f93ddd', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 4, 4, 'Is mass a scalar or a vector?', NULL, 1, 'multiple_choice'::answer_type, 'A scalar', NULL, false, NULL, false, NULL, 'Mass has magnitude only. Mark scheme (1 mark). B1: B (A scalar).', 1, NULL, NULL),
('4fb756e0-77e0-5967-9763-9893573b4515', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 5, 5, 'Two forces of 30 N and 40 N act at right angles on a box. Calculate the magnitude of the resultant force.', NULL, 1, 'numeric'::answer_type, '50', 'N', false, NULL, false, NULL, 'F = √(30² + 40²) = 50 N. Mark scheme (2 marks). C1: Pythagoras. A1: F = 50 N.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 260" role="img" aria-labelledby="fgd76fd0a0-t fgd76fd0a0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgd76fd0a0-t">Two perpendicular forces</title><desc id="fgd76fd0a0-d">Forces of 30 N and 40 N at right angles acting on a point, with their resultant dashed by the parallelogram rule.</desc><line x1="63.3" y1="210" x2="270.4" y2="210" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="276.7,210 268.5,213.8 268.5,206.2" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="290.7" y="214" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent,#1d4ed8)">40 N</text><line x1="63.3" y1="210" x2="63.3" y2="56.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="63.3,50 67.1,58.2 59.5,58.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="63.3" y="34" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">30 N</text><line x1="276.7" y1="210" x2="276.7" y2="50" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:3 3"/><line x1="63.3" y1="50" x2="276.7" y2="50" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;