('721a0d2d-0eba-52e2-84ef-e7f466e9144a', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 6, 6, 'Forces of 12 N east and 7.0 N west act on a trolley. Calculate the resultant force.', NULL, 1, 'numeric'::answer_type, '5', 'N', false, NULL, false, NULL, 'F = 12 − 7.0 = 5.0 N east. Mark scheme (2 marks). C1: subtract opposite forces. A1: F = 5.0 N.', 2, NULL, NULL),
('d07cf8b7-77b9-5cd9-906f-510d0d395f2f', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 7, 7, 'Is kinetic energy a scalar or a vector?', NULL, 1, 'multiple_choice'::answer_type, 'A scalar', NULL, false, NULL, false, NULL, 'Energy has no direction. Mark scheme (1 mark). B1: C (A scalar).', 1, NULL, NULL),
('c6ecaf05-524c-54d2-833f-951878cce5f5', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 8, 8, 'Which quantity is a vector?', NULL, 1, 'multiple_choice'::answer_type, 'Momentum', NULL, false, NULL, false, NULL, 'p = mv takes the direction of v. Mark scheme (1 mark). B1: A (Momentum).', 1, NULL, NULL),
('0d759996-f128-5a9e-9eb2-598ed18ccd16', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 9, 9, 'Two people push a car with forces of 300 N and 250 N in the same direction. Friction is 150 N. Calculate the resultant force.', NULL, 1, 'numeric'::answer_type, '400', 'N', false, NULL, false, NULL, 'F = 300 + 250 − 150 = 400 N. Mark scheme (2 marks). C1: add pushes, subtract friction. A1: F = 400 N.', 2, NULL, NULL),
('2c3469a4-10d0-5561-8943-00cb9b30f9b3', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 10, 10, 'Is electric charge a scalar or a vector?', NULL, 1, 'multiple_choice'::answer_type, 'A scalar (it can be positive or negative but has no direction)', NULL, false, NULL, false, NULL, 'A sign is not a direction. Mark scheme (1 mark). B1: D (A scalar (it can be positive or negative but has no direction)).', 1, NULL, NULL),
('aee82034-9464-5a45-8118-4bec8e9cfd30', '4653a171-76f9-4b44-bc1d-19802787195f', 'e1b6c84c-afbc-4845-b67b-d5b6bd15720c', 'a-level', '1.8', '9702 coursebook 1.8 · Other examples of scalar and vector quantities', 11, 11, 'Is acceleration a scalar or a vector?', NULL, 1, 'multiple_choice'::answer_type, 'A vector', NULL, false, NULL, false, NULL, 'a = Δv/Δt, and Δv is a vector. Mark scheme (1 mark). B1: B (A vector).', 1, NULL, NULL),
